import type { CrmCustomer, CrmFollowup, CrmStage } from '../../shared/types'

/**
 * 确保 CRM 客户管理相关的数据库表存在
 */
export async function ensureCrmTables(db: D1Database): Promise<void> {
  try {
    await db.prepare(`
      CREATE TABLE IF NOT EXISTS crm_customers (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        contact TEXT DEFAULT NULL,
        company TEXT DEFAULT NULL,
        group_id TEXT DEFAULT NULL,
        tag TEXT DEFAULT NULL,
        stage TEXT NOT NULL DEFAULT 'lead',
        country TEXT DEFAULT NULL,
        city TEXT DEFAULT NULL,
        ip TEXT DEFAULT NULL,
        source TEXT DEFAULT 'chat',
        source_conv_id TEXT DEFAULT NULL,
        remark TEXT DEFAULT NULL,
        owner_id TEXT DEFAULT NULL,
        owner_name TEXT DEFAULT NULL,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      )
    `).run()

    await db.prepare(`
      CREATE TABLE IF NOT EXISTS crm_followups (
        id TEXT PRIMARY KEY,
        customer_id TEXT NOT NULL,
        cycle_number INTEGER DEFAULT 1,
        agent_id TEXT NOT NULL,
        agent_name TEXT NOT NULL,
        content TEXT NOT NULL,
        next_followup_time INTEGER DEFAULT NULL,
        created_at INTEGER NOT NULL
      )
    `).run()

    try {
      await db.prepare('ALTER TABLE crm_customers ADD COLUMN cycle_number INTEGER DEFAULT 1').run()
      await db.prepare('ALTER TABLE crm_customers ADD COLUMN owner_username TEXT DEFAULT NULL').run()
      await db.prepare('ALTER TABLE crm_followups ADD COLUMN cycle_number INTEGER DEFAULT 1').run()
    } catch (e) {}
  } catch (e) {
    console.error('Failed to ensure CRM tables', e)
  }
}

export async function getCrmCustomers(
  db: D1Database,
  filter?: {
    search?: string
    stage?: string
    groupId?: string
    ownerId?: string
  }
): Promise<CrmCustomer[]> {
  await ensureCrmTables(db)

  let sql = 'SELECT * FROM crm_customers WHERE 1=1'
  const params: any[] = []

  if (filter?.search) {
    const s = `%${filter.search}%`
    sql += ' AND (name LIKE ? OR contact LIKE ? OR company LIKE ? OR tag LIKE ? OR remark LIKE ?)'
    params.push(s, s, s, s, s)
  }

  if (filter?.stage && filter.stage !== 'all') {
    sql += ' AND stage = ?'
    params.push(filter.stage)
  }

  if (filter?.groupId && filter.groupId !== 'all') {
    sql += ' AND group_id = ?'
    params.push(filter.groupId)
  }

  if (filter?.ownerId && filter.ownerId !== 'all') {
    sql += ' AND owner_id = ?'
    params.push(filter.ownerId)
  }

  sql += ' ORDER BY updated_at DESC LIMIT 200'

  let stmt = db.prepare(sql)
  if (params.length > 0) {
    stmt = stmt.bind(...params)
  }

  const res = await stmt.all<CrmCustomer>()
  return res.results || []
}

export async function createCrmCustomer(
  db: D1Database,
  data: Omit<CrmCustomer, 'id' | 'created_at' | 'updated_at'> & { id?: string }
): Promise<CrmCustomer> {
  await ensureCrmTables(db)

  const id = data.id || `crm_${crypto.randomUUID().slice(0, 10)}`
  const now = Date.now()

  await db.prepare(`
    INSERT INTO crm_customers (
      id, name, contact, company, group_id, tag, stage, cycle_number, country, city, ip,
      source, source_conv_id, remark, owner_id, owner_name, owner_username, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).bind(
    id,
    data.name,
    data.contact || null,
    data.company || null,
    data.group_id || 'grp_default',
    data.tag || null,
    data.stage || 'lead',
    data.cycle_number || 1,
    data.country || null,
    data.city || null,
    data.ip || null,
    data.source || 'chat',
    data.source_conv_id || null,
    data.remark || null,
    data.owner_id || null,
    data.owner_name || null,
    data.owner_username || null,
    now,
    now
  ).run()

  const created = await db.prepare('SELECT * FROM crm_customers WHERE id = ?').bind(id).first<CrmCustomer>()
  return created!
}

export async function updateCrmCustomer(
  db: D1Database,
  id: string,
  data: Partial<Omit<CrmCustomer, 'id' | 'created_at'>>
): Promise<CrmCustomer | null> {
  await ensureCrmTables(db)
  const now = Date.now()

  const fields: string[] = []
  const values: any[] = []

  for (const [k, v] of Object.entries(data)) {
    if (k !== 'id' && k !== 'created_at' && v !== undefined) {
      fields.push(`${k} = ?`)
      values.push(v)
    }
  }

  fields.push('updated_at = ?')
  values.push(now)
  values.push(id)

  await db.prepare(`UPDATE crm_customers SET ${fields.join(', ')} WHERE id = ?`).bind(...values).run()
  return await db.prepare('SELECT * FROM crm_customers WHERE id = ?').bind(id).first<CrmCustomer>()
}

export async function deleteCrmCustomer(db: D1Database, id: string): Promise<void> {
  await ensureCrmTables(db)
  await db.prepare('DELETE FROM crm_followups WHERE customer_id = ?').bind(id).run()
  await db.prepare('DELETE FROM crm_customers WHERE id = ?').bind(id).run()
}

export async function getCrmFollowups(
  db: D1Database,
  customerId?: string,
  cycleNumber?: number
): Promise<CrmFollowup[]> {
  await ensureCrmTables(db)
  let sql = 'SELECT * FROM crm_followups WHERE 1=1'
  const params: any[] = []

  if (customerId) {
    sql += ' AND customer_id = ?'
    params.push(customerId)
  }

  if (cycleNumber) {
    sql += ' AND cycle_number = ?'
    params.push(cycleNumber)
  }

  sql += ' ORDER BY created_at DESC LIMIT 150'
  let stmt = db.prepare(sql)
  if (params.length > 0) stmt = stmt.bind(...params)

  const res = await stmt.all<CrmFollowup>()
  return res.results || []
}

export async function createCrmFollowup(
  db: D1Database,
  data: Omit<CrmFollowup, 'id' | 'created_at'> & { new_stage?: CrmStage }
): Promise<CrmFollowup> {
  await ensureCrmTables(db)
  const id = `flw_${crypto.randomUUID().slice(0, 10)}`
  const now = Date.now()

  let cycle = data.cycle_number
  if (!cycle) {
    const cust = await db.prepare('SELECT cycle_number FROM crm_customers WHERE id = ?')
      .bind(data.customer_id).first<{ cycle_number: number }>()
    cycle = cust?.cycle_number || 1
  }

  await db.prepare(`
    INSERT INTO crm_followups (
      id, customer_id, cycle_number, agent_id, agent_name, content, next_followup_time, created_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
  `).bind(
    id,
    data.customer_id,
    cycle,
    data.agent_id,
    data.agent_name,
    data.content,
    data.next_followup_time || null,
    now
  ).run()

  if (data.new_stage) {
    await db.prepare('UPDATE crm_customers SET stage = ?, updated_at = ? WHERE id = ?')
      .bind(data.new_stage, now, data.customer_id).run()
  } else {
    await db.prepare('UPDATE crm_customers SET updated_at = ? WHERE id = ?').bind(now, data.customer_id).run()
  }

  const created = await db.prepare('SELECT * FROM crm_followups WHERE id = ?').bind(id).first<CrmFollowup>()
  return created!
}

/**
 * 为老客户开启下一轮成交复购周期 (Cycle Number + 1，阶段回到重点跟进)
 */
export async function startNewCustomerCycle(
  db: D1Database,
  customerId: string,
  agentId?: string,
  agentName?: string
): Promise<CrmCustomer> {
  await ensureCrmTables(db)
  const cust = await db.prepare('SELECT * FROM crm_customers WHERE id = ?').bind(customerId).first<CrmCustomer>()
  if (!cust) throw new Error('未找到该客户档案')

  const nextCycle = (cust.cycle_number || 1) + 1
  const now = Date.now()

  await db.prepare('UPDATE crm_customers SET cycle_number = ?, stage = ?, updated_at = ? WHERE id = ?')
    .bind(nextCycle, 'following', now, customerId).run()

  const flwId = `flw_${crypto.randomUUID().slice(0, 10)}`
  await db.prepare(`
    INSERT INTO crm_followups (
      id, customer_id, cycle_number, agent_id, agent_name, content, created_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?)
  `).bind(
    flwId,
    customerId,
    nextCycle,
    agentId || 'system',
    agentName || '系统',
    `【开启第 ${nextCycle} 轮成交复购周期】老客户再次咨询，开启新轮次推进`,
    now
  ).run()

  return (await db.prepare('SELECT * FROM crm_customers WHERE id = ?').bind(customerId).first<CrmCustomer>())!
}

export async function getCrmStats(db: D1Database): Promise<{
  total: number
  lead: number
  following: number
  quoted: number
  won: number
  lost: number
}> {
  await ensureCrmTables(db)
  const res = await db.prepare(`
    SELECT stage, COUNT(*) as count FROM crm_customers GROUP BY stage
  `).all<{ stage: CrmStage; count: number }>()

  const map: Record<string, number> = { lead: 0, following: 0, quoted: 0, won: 0, lost: 0 }
  let total = 0
  for (const r of res.results || []) {
    map[r.stage] = r.count
    total += r.count
  }

  return {
    total,
    lead: map.lead || 0,
    following: map.following || 0,
    quoted: map.quoted || 0,
    won: map.won || 0,
    lost: map.lost || 0
  }
}
