import { Hono } from 'hono'
import type { Env } from '../types'
import {
  getAllCustomForms,
  getCustomFormByKey,
  getCustomFormById,
  createCustomForm,
  updateCustomForm,
  deleteCustomForm,
  getFormSubmissions,
  insertFormSubmission,
  deleteFormSubmission
} from '../db/forms'
import { agentCanAccessSite, resolveSiteFromRequest } from '../db/sites'
import { isErrorResponse, requireAdmin, requireAgent } from '../middleware/auth'
import { clientIp, enforceRateLimit } from '../utils/rateLimit'
import { extractClientGeo } from '../utils/clientGeo'

export const formsRouter = new Hono<{ Bindings: Env }>()

function readSiteId(c: { req: { query: (k: string) => string | undefined; header: (k: string) => string | undefined } }, body?: any): string {
  return (
    (c.req.query('site_id') || '').trim() ||
    (c.req.header('X-Site-Id') || '').trim() ||
    (typeof body?.site_id === 'string' ? body.site_id.trim() : '')
  )
}

// ==================== 1. 后台管理接口 (Admin) ====================

formsRouter.get('/admin/forms', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const siteId = readSiteId(c)
    if (!siteId) {
      return c.json({ success: false, message: '请选择站点（site_id）' }, 400)
    }
    if (!(await agentCanAccessSite(c.env.DB, agent, siteId))) {
      return c.json({ success: false, message: '无权访问该站点表单' }, 403)
    }
    const list = await getAllCustomForms(c.env.DB, siteId)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

formsRouter.post('/admin/forms', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const body = await c.req.json()
    const { key, fields, style, translations_json } = body
    const siteId = readSiteId(c, body)

    if (!siteId) {
      return c.json({ success: false, message: '请选择站点（site_id）' }, 400)
    }
    if (!(await agentCanAccessSite(c.env.DB, admin, siteId))) {
      return c.json({ success: false, message: '无权在该站点创建表单' }, 403)
    }
    if (!key) {
      return c.json({ success: false, message: '表单调用 Key 为必填项' }, 400)
    }
    if (!translations_json || typeof translations_json !== 'object') {
      return c.json({ success: false, message: '请提供多语言文案 translations_json' }, 400)
    }
    const hasTitle = Object.values(translations_json as Record<string, any>).some(
      (b: any) => b?.title && String(b.title).trim()
    )
    if (!hasTitle) {
      return c.json({ success: false, message: '请至少填写一种语言的表单标题' }, 400)
    }

    const cleanedKey = key.trim().toLowerCase().replace(/[^a-z0-9_]/g, '_')
    const existing = await getCustomFormByKey(c.env.DB, cleanedKey, siteId)
    if (existing) {
      return c.json({ success: false, message: `调用 Key [${cleanedKey}] 在本站已存在，请更换` }, 400)
    }

    const created = await createCustomForm(c.env.DB, {
      key: cleanedKey,
      site_id: siteId,
      allowed_domains: '',
      fields: fields || [],
      style: style || {},
      translations_json
    })

    return c.json({ success: true, data: created })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

formsRouter.put('/admin/forms/:id', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const id = c.req.param('id')
    const body = await c.req.json()
    const { fields, style, translations_json } = body
    const siteId = readSiteId(c, body)

    const form = await getCustomFormById(c.env.DB, id)
    if (!form) {
      return c.json({ success: false, message: '表单不存在' }, 404)
    }
    const effectiveSiteId = siteId || form.site_id
    if (!effectiveSiteId || !(await agentCanAccessSite(c.env.DB, admin, effectiveSiteId))) {
      return c.json({ success: false, message: '无权修改该站点表单' }, 403)
    }
    if (form.site_id && siteId && form.site_id !== siteId) {
      return c.json({ success: false, message: '表单不属于当前站点' }, 403)
    }

    if (!translations_json || typeof translations_json !== 'object') {
      return c.json({ success: false, message: '请提供多语言文案 translations_json' }, 400)
    }
    const hasTitle = Object.values(translations_json as Record<string, any>).some(
      (b: any) => b?.title && String(b.title).trim()
    )
    if (!hasTitle) {
      return c.json({ success: false, message: '请至少填写一种语言的表单标题' }, 400)
    }

    await updateCustomForm(c.env.DB, id, {
      allowed_domains: '',
      fields: fields || [],
      style: style || {},
      translations_json
    })

    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

formsRouter.delete('/admin/forms/:id', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const id = c.req.param('id')
    const siteId = readSiteId(c)
    const form = await getCustomFormById(c.env.DB, id)
    if (!form) {
      return c.json({ success: false, message: '表单不存在' }, 404)
    }
    const effectiveSiteId = siteId || form.site_id
    if (!effectiveSiteId || !(await agentCanAccessSite(c.env.DB, admin, effectiveSiteId))) {
      return c.json({ success: false, message: '无权删除该站点表单' }, 403)
    }
    if (form.site_id && siteId && form.site_id !== siteId) {
      return c.json({ success: false, message: '表单不属于当前站点' }, 403)
    }
    await deleteCustomForm(c.env.DB, id)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

formsRouter.get('/admin/forms/:key/submissions', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const key = c.req.param('key')
    const siteId = readSiteId(c)
    if (!siteId) {
      return c.json({ success: false, message: '请选择站点（site_id）' }, 400)
    }
    if (!(await agentCanAccessSite(c.env.DB, agent, siteId))) {
      return c.json({ success: false, message: '无权查看该站点提交' }, 403)
    }
    const form = await getCustomFormByKey(c.env.DB, key, siteId)
    if (!form) {
      return c.json({ success: false, message: '表单不存在或不属于当前站点' }, 404)
    }
    const list = await getFormSubmissions(c.env.DB, key, siteId)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

formsRouter.delete('/admin/forms/submissions/:id', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const id = c.req.param('id')
    await deleteFormSubmission(c.env.DB, id)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

// ==================== 2. 前端嵌入式公开接口 (Public) ====================

/**
 * 前端嵌入组件获取表单配置信息 (GET)
 * 鉴权：Origin/Referer 解析站点，表单必须属于该站点
 */
formsRouter.get('/public/forms/:key', async (c) => {
  try {
    const key = c.req.param('key')
    const site = await resolveSiteFromRequest(c.env.DB, c.req.raw)
    if (!site || site.status !== 'active') {
      return c.json({ success: false, message: '当前域名未登记站点，无法加载表单' }, 403)
    }

    const form = await getCustomFormByKey(c.env.DB, key, site.id)

    if (!form || form.status === 'disabled') {
      return c.json({ success: false, message: '该表单不存在或已停用' }, 404)
    }

    return c.json({
      success: true,
      data: {
        key: form.key,
        site_id: form.site_id,
        fields: form.fields,
        style: form.style,
        translations_json: form.translations_json
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 前端嵌入组件提交表单数据 (POST)
 */
formsRouter.post('/public/forms/:key/submit', async (c) => {
  try {
    const rl = await enforceRateLimit({
      key: `form-submit:${clientIp(c)}`,
      limit: 30,
      windowSec: 300
    })
    if (!rl.ok) {
      return c.json({ success: false, message: '提交过于频繁，请稍后再试' }, 429)
    }

    const key = c.req.param('key')
    const site = await resolveSiteFromRequest(c.env.DB, c.req.raw)
    if (!site || site.status !== 'active') {
      return c.json({ success: false, message: '当前域名未登记站点，禁止提交' }, 403)
    }

    const form = await getCustomFormByKey(c.env.DB, key, site.id)

    if (!form || form.status === 'disabled') {
      return c.json({ success: false, message: '该表单不存在或已停用' }, 404)
    }

    const body = await c.req.json()
    const { visitor_id, data, source_url } = body

    if (!data || typeof data !== 'object') {
      return c.json({ success: false, message: '提交数据格式错误' }, 400)
    }

    // 必填字段校验（文案用字段 key，运行时 label 在前端）
    for (const field of form.fields) {
      if (field.required) {
        const val = data[field.key]
        if (val === undefined || val === null || val === '' || (Array.isArray(val) && val.length === 0)) {
          return c.json({ success: false, message: `请填写必填项：${field.key}` }, 400)
        }
      }
    }

    const geo = extractClientGeo(c.req.raw)

    const subId = await insertFormSubmission(c.env.DB, {
      form_key: key,
      site_id: site.id,
      visitor_id,
      data,
      ip: geo.ip,
      country: geo.country,
      city: geo.city,
      source_url: source_url || c.req.header('referer') || ''
    })

    return c.json({
      success: true,
      data: {
        id: subId,
        message: form.style?.success_message || '提交成功！'
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})
