import type { Context } from 'hono'
import type { Env, Agent } from '../types'
import { getAgentById } from '../db/auth'
import { verifyAgentToken } from '../utils/sessionToken'

function extractBearer(c: Context): string {
  const auth = c.req.header('Authorization') || c.req.header('authorization') || ''
  if (auth.startsWith('Bearer ')) return auth.slice(7).trim()
  return (c.req.header('x-session-token') || '').trim()
}

/** 要求已登录坐席：必须持有有效 HMAC 会话令牌（不再信任裸 x-agent-id） */
export async function requireAgent(
  c: Context<{ Bindings: Env }>
): Promise<Agent | Response> {
  const token = extractBearer(c)
  if (!token) {
    return c.json({ success: false, message: '未授权：请先登录' }, 401)
  }
  const payload = await verifyAgentToken(c.env, token)
  if (!payload) {
    return c.json({ success: false, message: '未授权：登录已失效，请重新登录' }, 401)
  }
  const agent = await getAgentById(c.env.DB, payload.id)
  if (!agent) {
    return c.json({ success: false, message: '未授权：坐席不存在或已失效' }, 401)
  }
  // 令牌角色与库不一致时以库为准，但拒绝伪造的 admin 提权痕迹
  if (payload.role === 'admin' && agent.role !== 'admin') {
    return c.json({ success: false, message: '未授权：权限已变更，请重新登录' }, 401)
  }
  return agent
}

/** 要求超级管理员 */
export async function requireAdmin(
  c: Context<{ Bindings: Env }>
): Promise<Agent | Response> {
  const agent = await requireAgent(c)
  if (agent instanceof Response) return agent
  if (agent.role !== 'admin') {
    return c.json({ success: false, message: '权限不足：仅超级管理员可操作' }, 403)
  }
  return agent
}

export function isErrorResponse(v: Agent | Response): v is Response {
  return v instanceof Response
}

/** 坐席令牌或（访客 id + 访客令牌）可访问会话资源 */
export async function requireAgentOrVisitorAccess(
  c: Context<{ Bindings: Env }>,
  conversationId: string,
  conversationVisitorId: string
): Promise<{ kind: 'agent'; agent: Agent } | { kind: 'visitor'; visitorId: string } | Response> {
  const token = extractBearer(c)
  if (token) {
    const agentPayload = await verifyAgentToken(c.env, token)
    if (agentPayload) {
      const agent = await getAgentById(c.env.DB, agentPayload.id)
      if (agent) return { kind: 'agent', agent }
    }
  }

  const { verifyVisitorToken } = await import('../utils/sessionToken')
  const visitorId = (c.req.query('visitor_id') || c.req.header('x-visitor-id') || '').trim()
  const visitorToken = (c.req.query('visitor_token') || c.req.header('x-visitor-token') || '').trim()
  if (
    visitorId &&
    visitorToken &&
    visitorId === conversationVisitorId &&
    (await verifyVisitorToken(c.env, visitorToken, visitorId, conversationId))
  ) {
    return { kind: 'visitor', visitorId }
  }

  return c.json({ success: false, message: '未授权：无权访问该会话' }, 401)
}
