export async function getSystemSettings(db: D1Database): Promise<Record<string, string>> {
  const res = await db.prepare('SELECT key, value FROM settings').all<{ key: string; value: string }>()
  const result: Record<string, string> = {
    widget_title: '在线专属客服',
    welcome_message: '您好！很高兴为您服务，请问有什么可以协助您的？',
    offline_message: '当前坐席暂未在线，请直接留言，我们稍后将回复您。',
    auto_reply_enabled: 'true',
    widget_brand_color: '#07c160',
    widget_position: 'bottom-right'
  }
  if (res.results) {
    for (const row of res.results) {
      result[row.key] = row.value
    }
  }
  return result
}

export async function getSystemSetting(db: D1Database, key: string): Promise<string | null> {
  const row = await db.prepare('SELECT value FROM settings WHERE key = ?').bind(key).first<{ value: string }>()
  return row?.value || null
}

export async function updateSystemSettings(db: D1Database, settings: Record<string, string>): Promise<void> {
  for (const [key, value] of Object.entries(settings)) {
    await db.prepare(
      'INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value'
    ).bind(key, value).run()
  }
}
