import { Hono } from 'hono'
import type { Env } from '../types'
import { isErrorResponse, requireAdmin, requireAgent } from '../middleware/auth'
import {
  agentCanAccessSite,
  createSite,
  deleteSite,
  getMergedSiteSettings,
  getSiteById,
  getSiteSettingsMap,
  listSitesForAgent,
  setAgentSites,
  getAgentSiteIds,
  updateSite,
  updateSiteSettings,
  isSiteSettingKey
} from '../db/sites'
import { updateSystemSettings } from '../db/settings'
import { getAllAgents } from '../db/auth'

export const sitesRouter = new Hono<{ Bindings: Env }>()

sitesRouter.get('/sites', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const list = await listSitesForAgent(c.env.DB, agent)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

sitesRouter.get('/sites/:id', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const id = c.req.param('id')
    if (!(await agentCanAccessSite(c.env.DB, agent, id))) {
      return c.json({ success: false, message: '无权访问该站点' }, 403)
    }
    const site = await getSiteById(c.env.DB, id)
    if (!site) return c.json({ success: false, message: '站点不存在' }, 404)
    return c.json({ success: true, data: site })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

sitesRouter.post('/sites', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const body = await c.req.json()
    const hosts = String(body.hosts || '')
      .split(/[\n,]+/)
      .map((s: string) => s.trim())
      .filter(Boolean)
    const site = await createSite(c.env.DB, {
      name: String(body.name || ''),
      hosts: Array.isArray(body.hosts) ? body.hosts : hosts,
      copy_from_site_id: body.copy_from_site_id || undefined
    })
    return c.json({ success: true, data: site })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 400)
  }
})

sitesRouter.put('/sites/:id', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const id = c.req.param('id')
    const body = await c.req.json()
    let hosts: string[] | undefined
    if (body.hosts !== undefined) {
      hosts = Array.isArray(body.hosts)
        ? body.hosts
        : String(body.hosts || '')
            .split(/[\n,]+/)
            .map((s: string) => s.trim())
            .filter(Boolean)
    }
    const site = await updateSite(c.env.DB, id, {
      name: body.name,
      status: body.status,
      hosts
    })
    return c.json({ success: true, data: site })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 400)
  }
})

sitesRouter.delete('/sites/:id', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    await deleteSite(c.env.DB, c.req.param('id'))
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/** 本站配置读写 */
sitesRouter.get('/sites/:id/settings', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const id = c.req.param('id')
    if (!(await agentCanAccessSite(c.env.DB, agent, id))) {
      return c.json({ success: false, message: '无权访问该站点' }, 403)
    }
    const merged = await getMergedSiteSettings(c.env.DB, id)
    const siteOnly = await getSiteSettingsMap(c.env.DB, id)
    return c.json({ success: true, data: { merged, site: siteOnly } })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

sitesRouter.post('/sites/:id/settings', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const id = c.req.param('id')
    const site = await getSiteById(c.env.DB, id)
    if (!site) return c.json({ success: false, message: '站点不存在' }, 404)
    const body = await c.req.json()
    const sitePatch: Record<string, string> = {}
    const globalPatch: Record<string, string> = {}
    for (const [k, v] of Object.entries(body || {})) {
      if (typeof v !== 'string') continue
      if (isSiteSettingKey(k)) sitePatch[k] = v
      else globalPatch[k] = v
    }
    if (Object.keys(sitePatch).length) await updateSiteSettings(c.env.DB, id, sitePatch)
    if (Object.keys(globalPatch).length) await updateSystemSettings(c.env.DB, globalPatch)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/** 坐席站点授权（仅 admin） */
sitesRouter.get('/agents/:id/sites', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const ids = await getAgentSiteIds(c.env.DB, c.req.param('id'))
    return c.json({ success: true, data: [...ids] })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

sitesRouter.put('/agents/:id/sites', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const body = await c.req.json()
    const siteIds: string[] = Array.isArray(body.site_ids) ? body.site_ids : []
    await setAgentSites(c.env.DB, c.req.param('id'), siteIds)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/** 调试：列出全部坐席及其站点（管理页用） */
sitesRouter.get('/agents-with-sites', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const agents = await getAllAgents(c.env.DB)
    const data = []
    for (const a of agents) {
      const ids = a.role === 'admin' ? null : [...(await getAgentSiteIds(c.env.DB, a.id))]
      data.push({ ...a, site_ids: ids })
    }
    return c.json({ success: true, data })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})
