// 一键从 CMS 产品与文章导入知识库 (避免重复录入)
kbRouter.post('/admin/kb/sync-from-cms', async (c) => {
  try {
    let importedCount = 0

    // 1. 同步 CMS 产品
    const productsRes = await getCmsProducts(c.env.DB, { pageSize: 100 })
    for (const p of productsRes.list) {
      const transZh = p.translations_json?.['zh-CN'] || Object.values(p.translations_json || {})[0]
      const title = p.title || transZh?.title || p.slug
      const description = transZh?.description || transZh?.summary || ''
      const spec = typeof transZh?.spec_data === 'object' ? JSON.stringify(transZh.spec_data) : (transZh?.spec_data || '')

      const content = `【产品型号/名称】: ${title}
【SKU】: ${p.sku || '默认'}
【品牌】: ${p.brand || '自有品牌'}
【价格】: ${p.price} ${p.price_currency}
【产品介绍】:
${description}
${spec ? `【规格参数】:\n${spec}` : ''}`

      const docId = `cms_prod_${p.id}`
      const doc: KbDocument = {
        id: docId,
        domain: 'product',
        title: `产品: ${title}`,
        content,
        rel_product_id: p.id,
        tags_json: JSON.stringify([p.brand, p.availability].filter(Boolean)),
        chunks_count: 0,
        status: 'ready',
        created_at: Date.now(),
        updated_at: Date.now()
      }

      await saveKbDocument(c.env.DB, doc)
      await indexDocument(c.env, doc)
      importedCount++
    }

    // 2. 同步 CMS 文章 (作为客服与 SEO 素材)
    const articlesRes = await getCmsArticles(c.env.DB, { pageSize: 100 })
    for (const a of articlesRes.list) {
      const transZh = a.translations_json?.['zh-CN'] || Object.values(a.translations_json || {})[0]
      const title = a.title || transZh?.title || a.slug
      const articleContent = transZh?.content || transZh?.summary || ''
      if (!articleContent.trim()) continue

      const content = `【文章标题】: ${title}
【作者/发布】: ${a.author || '企业官方'}
【正文/知识内容】:
${articleContent}`

      const docId = `cms_art_${a.id}`
      const doc: KbDocument = {
        id: docId,
        domain: 'support',
        title: `文章: ${title}`,
        content,
        rel_product_id: null,
        tags_json: JSON.stringify(['CMS文章']),
        chunks_count: 0,
        status: 'ready',
        created_at: Date.now(),
        updated_at: Date.now()
      }

      await saveKbDocument(c.env.DB, doc)
      await indexDocument(c.env, doc)
      importedCount++
    }

    return c.json({ status: 200, msg: `成功同步 ${importedCount} 条内容至知识库`, data: { count: importedCount } }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '从 CMS 同步失败: ' + err.message, data: null }, 500)
  }
})

// ==================== 3. AI 智能客服引擎与多模型池配置接口 ====================

// 获取 AI 客服引擎配置 (策略、人设与模型池)
kbRouter.get('/admin/kb/ai-config', async (c) => {
  try {
    const strategy = ((await getSystemSetting(c.env.DB, 'ai_reply_strategy')) as AiReplyStrategy) || 'always'
    const systemPrompt = (await getSystemSetting(c.env.DB, 'ai_system_prompt')) || ''
    const poolJson = await getSystemSetting(c.env.DB, 'ai_model_pool')
    let modelPool = DEFAULT_MODEL_POOL
    if (poolJson) {
      try {
        const parsed = JSON.parse(poolJson)
        if (Array.isArray(parsed) && parsed.length > 0) {
          modelPool = parsed
        }
      } catch (e) {}
    }

    const ticketAutoReplyStr = await getSystemSetting(c.env.DB, 'ai_ticket_auto_reply')
    const ticketAutoReply = ticketAutoReplyStr !== 'false'

    return c.json({
      status: 200,
      msg: 'ok',
      data: {
        strategy,
        system_prompt: systemPrompt,
        model_pool: modelPool,
        ticket_auto_reply: ticketAutoReply
      }
    }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '获取 AI 配置失败: ' + err.message, data: null }, 500)
  }
})

// 保存 AI 客服引擎配置
kbRouter.post('/admin/kb/ai-config', async (c) => {
  try {
    const body = await c.req.json() as Partial<AiEngineConfig>
    const updates: Record<string, string> = {}

    if (body.strategy) {
      updates['ai_reply_strategy'] = body.strategy
    }
    if (body.system_prompt !== undefined) {
      updates['ai_system_prompt'] = body.system_prompt
    }
    if (body.model_pool && Array.isArray(body.model_pool)) {
      updates['ai_model_pool'] = JSON.stringify(body.model_pool)
    }
    if (body.ticket_auto_reply !== undefined) {
      updates['ai_ticket_auto_reply'] = String(body.ticket_auto_reply)
    }

    await updateSystemSettings(c.env.DB, updates)

    return c.json({ status: 200, msg: 'AI 客服配置已更新并实时生效', data: null }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '保存 AI 配置失败: ' + err.message, data: null }, 500)
  }
})

// 单通道连通性测试 (供后台点击“测试连接”时调用)
kbRouter.post('/admin/kb/test-channel', async (c) => {
  try {
    const channel = await c.req.json() as AiModelChannel
    if (!channel || !channel.model) {
      return c.json({ status: 400, msg: '通道配置不完整', data: null }, 400)
    }

    const testRes = await testAiChannel(c.env, channel)
    return c.json({ status: 200, msg: 'ok', data: testRes }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: '测试异常: ' + err.message, data: null }, 500)
  }
})

// AI 一键多语言批量翻译 (基于模型轮换池，支持文本与保留 HTML 标签)
kbRouter.post('/admin/kb/translate', async (c) => {
  try {
    const body = await c.req.json() as AiTranslateParams
    if (!body || !body.sourceLang || !body.targetLangs || !body.fields) {
      return c.json({ status: 400, msg: '缺少翻译必要参数', data: null }, 400)
    }

    const result = await translateContentWithAi(c.env, body)
    return c.json({ status: 200, msg: 'ok', data: result }, 200)
  } catch (err: any) {
    return c.json({ status: 500, msg: 'AI 翻译异常: ' + err.message, data: null }, 500)
  }
})
