/**
 * 多站点：实体、域名解析、站点配置、坐席授权
 * 一个物理 host 只属于一个站点；未登记域名不可用挂件/聊天
 */

import type { Agent } from '../types'
import { getSystemSettings } from './settings'

export type SiteStatus = 'active' | 'disabled'

export type Site = {
  id: string
  name: string
  status: SiteStatus
  created_at: number
  updated_at: number
  hosts?: SiteHost[]
  primary_host?: string
}

export type SiteHost = {
  host: string
  site_id: string
  is_primary: number
  created_at: number
}

/** 归属站点的配置键（挂件 / 欢迎语 / 本站 GA） */
export const SITE_SETTING_KEYS = [
  'widget_title',
  'widget_brand_color',
  'widget_position',
  'widget_custom_icon',
  'widget_button_title',
  'widget_items_json',
  'welcome_message',
  'offline_message',
  'auto_reply_enabled',
  'ga_enabled',
  'ga_measurement_id',
  'ga_property_id',
  'ga_report_enabled'
] as const

const SITE_SETTING_KEY_SET = new Set<string>(SITE_SETTING_KEYS)

export function isSiteSettingKey(key: string): boolean {
  if (SITE_SETTING_KEY_SET.has(key)) return true
  // 多语言欢迎语 / 离线语
  return (
    key.startsWith('welcome_message_') ||
    key.startsWith('offline_message_')
  )
}

export function normalizeHost(raw: string): string {
  let h = (raw || '').trim().toLowerCase()
  if (!h) return ''
  // 去掉协议与路径
  try {
    if (h.includes('://')) h = new URL(h).hostname
    else if (h.includes('/')) h = h.split('/')[0]
  } catch {
    /* keep */
  }
  h = h.replace(/:\d+$/, '') // 去端口
  if (h.startsWith('www.')) h = h.slice(4)
  return h
}

export function hostFromRequest(req: Request, pageUrl?: string): string {
  const origin = req.headers.get('Origin') || ''
  if (origin) {
    try {
      return normalizeHost(new URL(origin).hostname)
    } catch {
      /* fall through */
    }
  }
  const referer = req.headers.get('Referer') || ''
  if (referer) {
    try {
      return normalizeHost(new URL(referer).hostname)
    } catch {
      /* fall through */
    }
  }
  if (pageUrl) {
    try {
      return normalizeHost(new URL(pageUrl).hostname)
    } catch {
      return normalizeHost(pageUrl)
    }
  }
  return ''
}

export async function ensureSitesSchema(db: D1Database): Promise<void> {
  await db
    .prepare(
      `CREATE TABLE IF NOT EXISTS sites (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'active',
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      )`
    )
    .run()
  await db
    .prepare(
      `CREATE TABLE IF NOT EXISTS site_hosts (
        host TEXT PRIMARY KEY,
        site_id TEXT NOT NULL,
        is_primary INTEGER NOT NULL DEFAULT 0,
        created_at INTEGER NOT NULL
      )`
    )
    .run()
  await db
    .prepare(
      `CREATE TABLE IF NOT EXISTS site_settings (
        site_id TEXT NOT NULL,
        key TEXT NOT NULL,
        value TEXT NOT NULL,
        PRIMARY KEY (site_id, key)
      )`
    )
    .run()
  await db
    .prepare(
      `CREATE TABLE IF NOT EXISTS agent_sites (
        agent_id TEXT NOT NULL,
        site_id TEXT NOT NULL,
        PRIMARY KEY (agent_id, site_id)
      )`
    )
    .run()

  try {
    await db.prepare('ALTER TABLE conversations ADD COLUMN site_id TEXT').run()
  } catch {
    /* exists */
  }
  try {
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_conversations_site ON conversations(site_id)').run()
  } catch {
    /* ignore */
  }
  try {
    await db.prepare('ALTER TABLE custom_forms ADD COLUMN site_id TEXT').run()
  } catch {
    /* exists */
  }
  try {
    await db.prepare('ALTER TABLE form_submissions ADD COLUMN site_id TEXT').run()
  } catch {
    /* exists */
  }
  try {
    await db.prepare('ALTER TABLE cms_categories ADD COLUMN site_id TEXT').run()
  } catch {
    /* exists */
  }
  try {
    await db.prepare('ALTER TABLE cms_articles ADD COLUMN site_id TEXT').run()
  } catch {
    /* exists */
  }
  try {
    await db.prepare('ALTER TABLE cms_products ADD COLUMN site_id TEXT').run()
  } catch {
    /* exists */
  }
}

async function attachHosts(db: D1Database, sites: Site[]): Promise<Site[]> {
  if (!sites.length) return sites
  const res = await db
    .prepare('SELECT host, site_id, is_primary, created_at FROM site_hosts ORDER BY is_primary DESC, host ASC')
    .all<SiteHost>()
  const bySite = new Map<string, SiteHost[]>()
  for (const h of res.results || []) {
    const list = bySite.get(h.site_id) || []
    list.push(h)
    bySite.set(h.site_id, list)
  }
  return sites.map(s => {
    const hosts = bySite.get(s.id) || []
    const primary = hosts.find(x => x.is_primary)?.host || hosts[0]?.host || ''
    return { ...s, hosts, primary_host: primary }
  })
}

export async function listSites(db: D1Database): Promise<Site[]> {
  await ensureSitesSchema(db)
  const res = await db
    .prepare('SELECT * FROM sites ORDER BY created_at ASC')
    .all<Site>()
  return attachHosts(db, res.results || [])
}

/** 坐席可见站点：admin 全部；agent 仅 agent_sites */
export async function listSitesForAgent(db: D1Database, agent: Agent): Promise<Site[]> {
  const all = await listSites(db)
  if (agent.role === 'admin') return all
  const allowed = await getAgentSiteIds(db, agent.id)
  return all.filter(s => allowed.has(s.id))
}

export async function getSiteById(db: D1Database, id: string): Promise<Site | null> {
  await ensureSitesSchema(db)
  const row = await db.prepare('SELECT * FROM sites WHERE id = ?').bind(id).first<Site>()
  if (!row) return null
  const [withHosts] = await attachHosts(db, [row])
  return withHosts
}

export async function resolveSiteByHost(
  db: D1Database,
  hostRaw: string
): Promise<Site | null> {
  await ensureSitesSchema(db)
  const host = normalizeHost(hostRaw)
  if (!host) return null
  // localhost 开发：若库中登记了 localhost / 127.0.0.1 则用该站；否则取第一个 active 站
  const row = await db
    .prepare('SELECT site_id FROM site_hosts WHERE host = ?')
    .bind(host)
    .first<{ site_id: string }>()
  if (row?.site_id) {
    const site = await getSiteById(db, row.site_id)
    if (site && site.status === 'active') return site
    return null
  }
  if (host === 'localhost' || host === '127.0.0.1') {
    const first = await db
      .prepare("SELECT * FROM sites WHERE status = 'active' ORDER BY created_at ASC LIMIT 1")
      .first<Site>()
    if (!first) return null
    const [withHosts] = await attachHosts(db, [first])
    return withHosts
  }
  return null
}

export async function createSite(
  db: D1Database,
  data: { name: string; hosts: string[]; copy_from_site_id?: string }
): Promise<Site> {
  await ensureSitesSchema(db)
  const name = data.name.trim()
  if (!name) throw new Error('站点名称不能为空')
  const hosts = [...new Set(data.hosts.map(normalizeHost).filter(Boolean))]
  if (!hosts.length) throw new Error('至少登记一个域名')

  for (const h of hosts) {
    const taken = await db
      .prepare('SELECT site_id FROM site_hosts WHERE host = ?')
      .bind(h)
      .first<{ site_id: string }>()
    if (taken) throw new Error(`域名 ${h} 已归属其他站点`)
  }

  const id = `site_${crypto.randomUUID().slice(0, 8)}`
  const now = Date.now()
  await db
    .prepare(
      `INSERT INTO sites (id, name, status, created_at, updated_at) VALUES (?, ?, 'active', ?, ?)`
    )
    .bind(id, name, now, now)
    .run()

  for (let i = 0; i < hosts.length; i++) {
    await db
      .prepare(
        `INSERT INTO site_hosts (host, site_id, is_primary, created_at) VALUES (?, ?, ?, ?)`
      )
      .bind(hosts[i], id, i === 0 ? 1 : 0, now)
      .run()
  }

  // 从模板站复制配置，否则写入默认挂件配置
  if (data.copy_from_site_id) {
    const src = await getSiteSettingsMap(db, data.copy_from_site_id)
    if (Object.keys(src).length) {
      await updateSiteSettings(db, id, src)
    }
  } else {
    await updateSiteSettings(db, id, {
      widget_brand_color: '#07c160',
      widget_position: 'bottom-right',
      widget_button_title: '在线客服',
      welcome_message: '您好！很高兴为您服务，请问有什么可以协助您的？',
      offline_message: '当前坐席暂未在线，请直接留言，我们稍后将回复您。',
      auto_reply_enabled: 'true'
    })
  }

  const site = await getSiteById(db, id)
  return site!
}

export async function updateSite(
  db: D1Database,
  id: string,
  data: { name?: string; status?: SiteStatus; hosts?: string[] }
): Promise<Site> {
  await ensureSitesSchema(db)
  const existing = await getSiteById(db, id)
  if (!existing) throw new Error('站点不存在')

  const now = Date.now()
  if (data.name !== undefined) {
    const name = data.name.trim()
    if (!name) throw new Error('站点名称不能为空')
    await db
      .prepare('UPDATE sites SET name = ?, updated_at = ? WHERE id = ?')
      .bind(name, now, id)
      .run()
  }
  if (data.status !== undefined) {
    await db
      .prepare('UPDATE sites SET status = ?, updated_at = ? WHERE id = ?')
      .bind(data.status, now, id)
      .run()
  }

  if (data.hosts !== undefined) {
    const hosts = [...new Set(data.hosts.map(normalizeHost).filter(Boolean))]
    if (!hosts.length) throw new Error('至少登记一个域名')
    for (const h of hosts) {
      const taken = await db
        .prepare('SELECT site_id FROM site_hosts WHERE host = ?')
        .bind(h)
        .first<{ site_id: string }>()
      if (taken && taken.site_id !== id) {
        throw new Error(`域名 ${h} 已归属其他站点`)
      }
    }
    await db.prepare('DELETE FROM site_hosts WHERE site_id = ?').bind(id).run()
    for (let i = 0; i < hosts.length; i++) {
      await db
        .prepare(
          `INSERT INTO site_hosts (host, site_id, is_primary, created_at) VALUES (?, ?, ?, ?)`
        )
        .bind(hosts[i], id, i === 0 ? 1 : 0, now)
        .run()
    }
    await db.prepare('UPDATE sites SET updated_at = ? WHERE id = ?').bind(now, id).run()
  }

  const site = await getSiteById(db, id)
  return site!
}

export async function deleteSite(db: D1Database, id: string): Promise<void> {
  await ensureSitesSchema(db)
  await db.prepare('DELETE FROM site_hosts WHERE site_id = ?').bind(id).run()
  await db.prepare('DELETE FROM site_settings WHERE site_id = ?').bind(id).run()
  await db.prepare('DELETE FROM agent_sites WHERE site_id = ?').bind(id).run()
  await db.prepare('DELETE FROM sites WHERE id = ?').bind(id).run()
}

export async function getSiteSettingsMap(
  db: D1Database,
  siteId: string
): Promise<Record<string, string>> {
  await ensureSitesSchema(db)
  const res = await db
    .prepare('SELECT key, value FROM site_settings WHERE site_id = ?')
    .bind(siteId)
    .all<{ key: string; value: string }>()
  const map: Record<string, string> = {}
  for (const row of res.results || []) map[row.key] = row.value
  return map
}

/**
 * 站点配置 ⊕ 全局兜底（仅对站点键：站点有值用站点，否则用全局）
 */
export async function getMergedSiteSettings(
  db: D1Database,
  siteId: string
): Promise<Record<string, string>> {
  const global = await getSystemSettings(db)
  const site = await getSiteSettingsMap(db, siteId)
  const merged = { ...global }
  for (const [k, v] of Object.entries(site)) {
    merged[k] = v
  }
  // 若站点未设某挂件键，保留全局默认（getSystemSettings 已带默认）
  return merged
}

export async function updateSiteSettings(
  db: D1Database,
  siteId: string,
  settings: Record<string, string>
): Promise<void> {
  await ensureSitesSchema(db)
  for (const [key, value] of Object.entries(settings)) {
    if (!isSiteSettingKey(key)) continue
    await db
      .prepare(
        `INSERT INTO site_settings (site_id, key, value) VALUES (?, ?, ?)
         ON CONFLICT(site_id, key) DO UPDATE SET value = excluded.value`
      )
      .bind(siteId, key, value)
      .run()
  }
}

export async function getAgentSiteIds(db: D1Database, agentId: string): Promise<Set<string>> {
  await ensureSitesSchema(db)
  const res = await db
    .prepare('SELECT site_id FROM agent_sites WHERE agent_id = ?')
    .bind(agentId)
    .all<{ site_id: string }>()
  return new Set((res.results || []).map(r => r.site_id))
}

export async function setAgentSites(
  db: D1Database,
  agentId: string,
  siteIds: string[]
): Promise<void> {
  await ensureSitesSchema(db)
  await db.prepare('DELETE FROM agent_sites WHERE agent_id = ?').bind(agentId).run()
  const uniq = [...new Set(siteIds.filter(Boolean))]
  for (const sid of uniq) {
    await db
      .prepare('INSERT INTO agent_sites (agent_id, site_id) VALUES (?, ?)')
      .bind(agentId, sid)
      .run()
  }
}

export async function agentCanAccessSite(
  db: D1Database,
  agent: Agent,
  siteId: string
): Promise<boolean> {
  if (!siteId) return false
  if (agent.role === 'admin') return true
  const ids = await getAgentSiteIds(db, agent.id)
  return ids.has(siteId)
}

/** 从请求解析站点；失败返回 null */
export async function resolveSiteFromRequest(
  db: D1Database,
  req: Request,
  pageUrl?: string
): Promise<Site | null> {
  const host = hostFromRequest(req, pageUrl)
  if (!host) return null
  return resolveSiteByHost(db, host)
}
