import { Hono } from 'hono'
import type { Env } from '../types'
import {
  getOrCreateConversation,
  getConversations,
  deleteConversation,
  countConversationMedia,
  updateConversationContext,
  getVisitorJourneyLogs
} from '../db/conversations'
import { getMessagesByConversation, markConversationAsRead } from '../db/messages'
import { ensureDefaultAdmin, getAgentById } from '../db/auth'
import { getLanguages } from '../db/i18n'
import { getSettingForLang, DEFAULT_WELCOME_ZH } from '../../shared/langSettings'
import { isErrorResponse, requireAdmin, requireAgent, requireAgentOrVisitorAccess } from '../middleware/auth'
import { issueVisitorToken, internalRequestHeaders } from '../utils/sessionToken'
import { clientIp, enforceRateLimit } from '../utils/rateLimit'
import { extractClientGeo } from '../utils/clientGeo'
import {
  agentCanAccessSite,
  getMergedSiteSettings,
  resolveSiteFromRequest
} from '../db/sites'

export const chatRouter = new Hono<{ Bindings: Env }>()

chatRouter.post('/visitor/init', async (c) => {
  try {
    const rl = await enforceRateLimit({
      key: `visitor-init:${clientIp(c)}`,
      limit: 60,
      windowSec: 60
    })
    if (!rl.ok) {
      return c.json({ success: false, message: '请求过于频繁，请稍后再试' }, 429)
    }

    await ensureDefaultAdmin(c.env.DB)
    const body = await c.req.json()
    const {
      visitor_id,
      visitor_name,
      visitor_lang,
      conversation_id,
      messages_after,
      page_context,
      product_snapshot,
      device_info
    } = body
    if (!visitor_id) {
      return c.json({ success: false, message: '缺少访客唯一标识' }, 400)
    }

    const pageUrl =
      page_context && typeof page_context === 'object' ? (page_context as any).url : undefined
    const site = await resolveSiteFromRequest(c.env.DB, c.req.raw, pageUrl)
    if (!site) {
      return c.json(
        { success: false, message: '当前域名未登记为授权站点，无法使用客服' },
        403
      )
    }

    // 后台已彻底删除该会话：要求前端清空本地 visitor id，当作新访客
    if (conversation_id) {
      const stillThere = await c.env.DB.prepare(
        'SELECT id FROM conversations WHERE id = ? AND site_id = ?'
      )
        .bind(conversation_id, site.id)
        .first<{ id: string }>()
      if (!stillThere) {
        return c.json({
          success: true,
          data: { reset_identity: true, reason: 'conversation_deleted' }
        })
      }
    }

    const clientTzHint =
      (device_info && typeof device_info === 'object' && (device_info as any).timezone) ||
      null
    const geo = extractClientGeo(c.req.raw, clientTzHint)

    const { conversation, isNew } = await getOrCreateConversation(
      c.env.DB,
      visitor_id,
      site.id,
      visitor_name,
      visitor_lang,
      {
        ip: geo.ip || undefined,
        country: geo.country || undefined,
        city: geo.city || undefined,
        isp: geo.isp || undefined,
        timezone: geo.timezone || undefined
      },
      { page_context, product_snapshot, device_info }
    )
    const afterTs = Number(messages_after) > 0 ? Number(messages_after) : undefined
    const messages = await getMessagesByConversation(c.env.DB, conversation.id, 40, undefined, afterTs)

    // 新会话立即通知坐席工作台（无需等访客先发消息）
    if (isNew && c.env.COORDINATOR) {
      try {
        const stub = c.env.COORDINATOR.get(c.env.COORDINATOR.idFromName('global_chat_coordinator'))
        await stub.fetch(
          new Request('http://coordinator/broadcast-message', {
            method: 'POST',
            headers: internalRequestHeaders(c.env),
            body: JSON.stringify({
              conversation_id: conversation.id,
              id: `sys_init_${conversation.id}`,
              sender_type: 'agent',
              sender_id: 'system',
              content: conversation.last_message_text || '',
              message_type: 'text',
              created_at: conversation.created_at || Date.now()
            })
          })
        )
      } catch {
        /* 广播失败不影响 init */
      }
    }

    const visitor_token = await issueVisitorToken(c.env, visitor_id, conversation.id)

    return c.json({
      success: true,
      data: {
        conversation,
        messages,
        isNew,
        visitor_token
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

// 访客端上报页面上下文变化与足迹 (SPA 路由切换与浏览行为)
chatRouter.post('/visitor/context', async (c) => {
  try {
    const { conversation_id, visitor_id, page_context, product_snapshot, device_info } = await c.req.json()
    if (!conversation_id || !visitor_id || !page_context) {
      return c.json({ success: false, message: '参数不完整' }, 400)
    }
    const access = await requireAgentOrVisitorAccess(c, conversation_id, visitor_id)
    if (access instanceof Response) return access
    if (access.kind === 'visitor' && access.visitorId !== visitor_id) {
      return c.json({ success: false, message: '未授权：会话不匹配' }, 403)
    }
    const owned = await c.env.DB.prepare('SELECT id FROM conversations WHERE id = ? AND visitor_id = ?')
      .bind(conversation_id, visitor_id)
      .first()
    if (!owned) {
      return c.json({ success: false, message: '未授权：会话不匹配' }, 403)
    }

    // 每次上下文上报顺带用本次真实客户端连接刷新地理（纠正历史错误 IP）
    const clientTzHint =
      (device_info && typeof device_info === 'object' && (device_info as any).timezone) ||
      null
    const geo = extractClientGeo(c.req.raw, clientTzHint)
    if (geo.ip || geo.country || geo.timezone) {
      await c.env.DB.prepare(
        `UPDATE conversations SET
          ip = CASE WHEN ? IS NOT NULL AND ? != '' THEN ? ELSE ip END,
          country = CASE WHEN ? IS NOT NULL AND ? != '' THEN ? ELSE country END,
          city = CASE WHEN ? IS NOT NULL AND ? != '' THEN ? ELSE city END,
          isp = CASE WHEN ? IS NOT NULL AND ? != '' THEN ? ELSE isp END,
          timezone = CASE WHEN ? IS NOT NULL AND ? != '' THEN ? ELSE timezone END
        WHERE id = ? AND visitor_id = ?`
      )
        .bind(
          geo.ip, geo.ip, geo.ip,
          geo.country, geo.country, geo.country,
          geo.city, geo.city, geo.city,
          geo.isp, geo.isp, geo.isp,
          geo.timezone, geo.timezone, geo.timezone,
          conversation_id,
          visitor_id
        )
        .run()
        .catch(() => {})
    }

    const ok = await updateConversationContext(
      c.env.DB,
      conversation_id,
      visitor_id,
      page_context,
      product_snapshot,
      device_info
    )
    return c.json({ success: ok })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

// 客服端获取访客浏览旅程轨迹
chatRouter.get('/conversations/:id/journey', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const convId = c.req.param('id')
    const list = await getVisitorJourneyLogs(c.env.DB, convId)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

chatRouter.get('/conversations', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const platform = c.req.query('platform') || undefined
    const siteId = (c.req.query('site_id') || '').trim()
    if (!siteId) {
      return c.json({ success: false, message: '请选择站点（site_id）' }, 400)
    }
    if (!(await agentCanAccessSite(c.env.DB, agent, siteId))) {
      return c.json({ success: false, message: '无权访问该站点会话' }, 403)
    }
    const list = await getConversations(c.env.DB, { siteId, platform })
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

chatRouter.get('/conversations/:id/messages', async (c) => {
  try {
    const convId = c.req.param('id')
    const conv = await c.env.DB.prepare('SELECT id, visitor_id FROM conversations WHERE id = ?')
      .bind(convId)
      .first<{ id: string; visitor_id: string }>()
    if (!conv) return c.json({ success: false, message: '会话不存在' }, 404)

    const access = await requireAgentOrVisitorAccess(c, conv.id, conv.visitor_id)
    if (access instanceof Response) return access

    const limit = Number(c.req.query('limit')) || 40
    const before = Number(c.req.query('before')) || undefined
    const after = Number(c.req.query('after')) || undefined
    const messages = await getMessagesByConversation(c.env.DB, convId, limit, before, after)
    return c.json({ success: true, data: messages })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

chatRouter.post('/conversations/:id/read', async (c) => {
  try {
    const convId = c.req.param('id')
    const conv = await c.env.DB.prepare('SELECT id, visitor_id FROM conversations WHERE id = ?')
      .bind(convId)
      .first<{ id: string; visitor_id: string }>()
    if (!conv) return c.json({ success: false, message: '会话不存在' }, 404)
    const access = await requireAgentOrVisitorAccess(c, conv.id, conv.visitor_id)
    if (access instanceof Response) return access

    const { by } = await c.req.json()
    if (by) {
      await markConversationAsRead(c.env.DB, convId, by)
    }
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/** 删除前提示：该会话关联的 R2 媒体数量 */
chatRouter.get('/conversations/:id/media-count', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const convId = c.req.param('id')
    const count = await countConversationMedia(c.env.DB, convId)
    return c.json({ success: true, data: { count } })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 彻底删除某个客户的会话以及该会话下的所有聊天记录 (仅超级管理员)
 * 会同步删除 R2 媒体，并通知在线访客清空本地身份
 */
chatRouter.delete('/conversations/:id', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const convId = c.req.param('id')

    // 先通知在线访客（删除前仍能按 cid 找到 socket）
    if (c.env.COORDINATOR) {
      try {
        const stub = c.env.COORDINATOR.get(c.env.COORDINATOR.idFromName('global_chat_coordinator'))
        await stub.fetch(
          new Request('http://coordinator/broadcast-deleted', {
            method: 'POST',
            headers: internalRequestHeaders(c.env),
            body: JSON.stringify({
              conversation_id: convId,
              clear_identity: true
            })
          })
        )
      } catch {
        /* ignore */
      }
    }

    const result = await deleteConversation(c.env.DB, convId, c.env.MEDIA_BUCKET)
    return c.json({
      success: true,
      data: { mediaCount: result.mediaCount, visitorId: result.visitorId }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 设置/修改客户备注标记 (tag)
 */
chatRouter.post('/conversations/:id/tag', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const convId = c.req.param('id')
    const { tag } = await c.req.json()
    const { updateConversationTag } = await import('../db/conversations')
    await updateConversationTag(c.env.DB, convId, tag ? tag.trim() : null)
    return c.json({ success: true, tag })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 一键批量清理垃圾会话（支持未发言访客、分组、标记维度）
 */
chatRouter.post('/admin/conversations/batch-cleanup', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const body = await c.req.json()
    const { clean_silent, group_ids, tag_mode } = body
    const { batchCleanupConversations } = await import('../db/conversations')
    const count = await batchCleanupConversations(c.env.DB, c.env.MEDIA_BUCKET, {
      cleanSilent: clean_silent,
      groupIds: group_ids,
      tagMode: tag_mode
    })
    return c.json({ success: true, deleted_count: count })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 访客端挂件配置：按请求 Origin/Referer 解析站点；未登记域名 403
 */
chatRouter.get('/widget/config', async (c) => {
  try {
    const hostHint = (c.req.query('host') || '').trim()
    const site = hostHint
      ? await resolveSiteFromRequest(c.env.DB, c.req.raw, `https://${hostHint}/`)
      : await resolveSiteFromRequest(c.env.DB, c.req.raw)
    if (!site) {
      c.header('Cache-Control', 'no-store')
      return c.json(
        { success: false, message: '当前域名未登记为授权站点', code: 'site_not_allowed' },
        403
      )
    }

    const settingsMap = await getMergedSiteSettings(c.env.DB, site.id)
    const brand_color = settingsMap.widget_brand_color || '#07c160'
    const position = settingsMap.widget_position || 'bottom-right'
    const custom_icon = settingsMap.widget_custom_icon || ''
    const button_title = settingsMap.widget_button_title || '在线客服'
    const widget_items_json = settingsMap.widget_items_json || ''
    const ga_enabled = settingsMap.ga_enabled === '1'
    const ga_measurement_id = settingsMap.ga_measurement_id || ''
    const langs = await getLanguages(c.env.DB)
    const welcome_messages: Record<string, string> = {}
    for (const lang of langs) {
      welcome_messages[lang.code] = getSettingForLang(
        settingsMap,
        'welcome_message',
        lang.code,
        ''
      )
    }
    const welcome_message =
      welcome_messages['zh-CN'] ||
      welcome_messages['en'] ||
      settingsMap.welcome_message ||
      settingsMap.welcome_message_zh ||
      DEFAULT_WELCOME_ZH

    // 按站点缓存，避免多站串配置
    c.header('Cache-Control', 'public, max-age=300, s-maxage=300')
    c.header('Vary', 'Origin')

    return c.json({
      success: true,
      data: {
        site_id: site.id,
        site_name: site.name,
        brand_color,
        position,
        custom_icon,
        button_title,
        widget_items_json,
        welcome_message,
        welcome_messages,
        ga_enabled,
        ga_measurement_id: ga_enabled ? ga_measurement_id : ''
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/**
 * 访客提交邮件/离线留言：无论是否配置邮件通道，都必须落库到会话，坐席工作台可见
 */
chatRouter.post('/visitor/ticket', async (c) => {
  try {
    const rl = await enforceRateLimit({
      key: `ticket:${clientIp(c)}`,
      limit: 15,
      windowSec: 300
    })
    if (!rl.ok) {
      return c.json({ success: false, message: '提交过于频繁，请稍后再试' }, 429)
    }

    const {
      visitor_id,
      visitor_name,
      contact,
      content,
      conversation_id,
      extra_fields,
      source_url
    } = await c.req.json()
    if (!content || !contact) {
      return c.json({ success: false, message: '请完整填写联系方式与留言内容' }, 400)
    }

    const name = String(visitor_name || '访客').trim().slice(0, 64) || '访客'
    const contactStr = String(contact).trim().slice(0, 200)
    const contentStr = String(content).trim().slice(0, 4000)
    const vid = String(visitor_id || '').trim() || `v_ticket_${crypto.randomUUID().slice(0, 8)}`
    const now = Date.now()

    let extraText = ''
    if (extra_fields && typeof extra_fields === 'object') {
      const lines: string[] = []
      for (const [k, v] of Object.entries(extra_fields)) {
        if (k !== 'name' && k !== 'contact' && k !== 'content' && v) {
          lines.push(`${k}: ${Array.isArray(v) ? v.join(', ') : v}`)
        }
      }
      if (lines.length > 0) {
        extraText = `\n【扩展字段】\n` + lines.join('\n')
      }
    }
    const srcLine = source_url ? `\n来源页：${String(source_url).slice(0, 500)}` : ''
    const ticketContent =
      `【邮件留言】\n称呼：${name}\n联系方式：${contactStr}\n留言内容：${contentStr}${extraText}${srcLine}`

    const site = await resolveSiteFromRequest(
      c.env.DB,
      c.req.raw,
      typeof source_url === 'string' ? source_url : undefined
    )
    if (!site) {
      return c.json({ success: false, message: '当前域名未登记为授权站点' }, 403)
    }

    // 1. 始终绑定会话并写消息（无 conversation_id 时按 visitor+站点 创建/复用）
    let convId = typeof conversation_id === 'string' ? conversation_id.trim() : ''
    if (!convId || convId.startsWith('pending_')) {
      const { conversation } = await getOrCreateConversation(c.env.DB, vid, site.id, name)
      convId = conversation.id
    } else {
      const exists = await c.env.DB.prepare(
        'SELECT id, visitor_id FROM conversations WHERE id = ? AND site_id = ?'
      )
        .bind(convId, site.id)
        .first<{ id: string; visitor_id: string }>()
      if (!exists) {
        const { conversation } = await getOrCreateConversation(c.env.DB, vid, site.id, name)
        convId = conversation.id
      }
    }

    const msgId = 'msg_' + crypto.randomUUID().slice(0, 10)
    await c.env.DB.prepare(
      `INSERT INTO messages (
        id, conversation_id, sender_type, sender_id, sender_name,
        message_type, content, status, created_at
      ) VALUES (?, ?, 'visitor', ?, ?, 'text', ?, 'sent', ?)`
    )
      .bind(msgId, convId, vid, name, ticketContent, now)
      .run()

    await c.env.DB.prepare(
      `UPDATE conversations SET
        visitor_name = ?,
        last_message_text = ?,
        last_message_time = ?,
        unread_agent_count = unread_agent_count + 1,
        tag = COALESCE(NULLIF(tag, ''), '邮件留言')
      WHERE id = ?`
    )
      .bind(name, ticketContent.slice(0, 200), now, convId)
      .run()

    try {
      const stub = c.env.COORDINATOR.get(c.env.COORDINATOR.idFromName('global_chat_coordinator'))
      await stub.fetch(
        new Request('http://coordinator/broadcast-message', {
          method: 'POST',
          headers: internalRequestHeaders(c.env),
          body: JSON.stringify({
            id: msgId,
            conversation_id: convId,
            sender_type: 'visitor',
            sender_id: vid,
            sender_name: name,
            message_type: 'text',
            content: ticketContent,
            status: 'sent',
            created_at: now
          })
        })
      )
    } catch (e) {}

    // 2. 已配置的通知渠道尽力推送（失败不影响落库）
    const { dispatchLeaveMessageNotification } = await import('../services/notifier')
    const notifyRes = await dispatchLeaveMessageNotification(c.env, {
      visitor_name: name,
      contact: contactStr,
      content: contentStr,
      conversation_id: convId,
      visitor_id: vid
    }).catch(() => ({ ok: false as const }))

    // 3. AI 预答复（可选）
    c.executionCtx.waitUntil(
      (async () => {
        try {
          const { askKnowledge } = await import('../services/kbService')
          const { answer } = await askKnowledge(c.env, contentStr)
          if (!answer) return
          const aiReplyText = `【AI 智能预答复】\n我们已收到您的留言并已提醒人工客服稍后跟进！根据企业知识库，初步为您查询到以下参考信息：\n\n${answer}`
          const aiMsgId = 'msg_' + crypto.randomUUID().slice(0, 10)
          const aiNow = Date.now()
          await c.env.DB.prepare(
            `INSERT INTO messages (
              id, conversation_id, sender_type, sender_id, sender_name,
              message_type, content, status, created_at
            ) VALUES (?, ?, 'agent', 'ai_bot', 'AI 智能客服', 'text', ?, 'sent', ?)`
          )
            .bind(aiMsgId, convId, aiReplyText, aiNow)
            .run()

          await c.env.DB.prepare(
            'UPDATE conversations SET last_message_text = ?, last_message_time = ? WHERE id = ?'
          )
            .bind(aiReplyText.slice(0, 200), aiNow, convId)
            .run()

          const stub = c.env.COORDINATOR.get(c.env.COORDINATOR.idFromName('global_chat_coordinator'))
          await stub.fetch(
            new Request('http://coordinator/broadcast-message', {
              method: 'POST',
              headers: internalRequestHeaders(c.env),
              body: JSON.stringify({
                id: aiMsgId,
                conversation_id: convId,
                sender_type: 'agent',
                sender_id: 'ai_bot',
                sender_name: 'AI 智能客服',
                message_type: 'text',
                content: aiReplyText,
                status: 'sent',
                created_at: aiNow
              })
            })
          )
        } catch (e) {
          console.warn('Failed to generate ticket pre-reply with KB', e)
        }
      })()
    )

    return c.json({
      success: true,
      message: '您的留言已成功提交，客服将尽快与您联系！',
      data: { conversation_id: convId, message_id: msgId, notify: notifyRes }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})
