import { Hono } from 'hono'
import type { Env } from '../types'
import {
  getCrmCustomers,
  createCrmCustomer,
  updateCrmCustomer,
  deleteCrmCustomer,
  getCrmFollowups,
  createCrmFollowup,
  startNewCustomerCycle,
  getCrmStats
} from '../db/crm'
import { isErrorResponse, requireAdmin, requireAgent } from '../middleware/auth'

export const crmRouter = new Hono<{ Bindings: Env }>()

crmRouter.get('/crm/customers', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const search = c.req.query('search')
    const stage = c.req.query('stage')
    const groupId = c.req.query('group_id')
    const ownerId = c.req.query('owner_id')

    const list = await getCrmCustomers(c.env.DB, {
      search,
      stage,
      groupId,
      ownerId
    })
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

crmRouter.post('/crm/customers', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const body = await c.req.json()
    if (!body.name || !body.name.trim()) {
      return c.json({ success: false, message: '客户姓名不能为空' }, 400)
    }

    const customer = await createCrmCustomer(c.env.DB, {
      name: body.name.trim(),
      contact: body.contact ? body.contact.trim() : null,
      company: body.company ? body.company.trim() : null,
      group_id: body.group_id || 'grp_default',
      tag: body.tag ? body.tag.trim() : null,
      stage: body.stage || 'lead',
      country: body.country || null,
      city: body.city || null,
      ip: body.ip || null,
      source: body.source || 'chat',
      source_conv_id: body.source_conv_id || null,
      remark: body.remark ? body.remark.trim() : null,
      owner_id: body.owner_id || agent.id,
      owner_name: body.owner_name || agent.display_name,
      owner_username: body.owner_username
        ? body.owner_username.trim()
        : agent.username
    })

    return c.json({ success: true, data: customer })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

crmRouter.put('/crm/customers/:id', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const id = c.req.param('id')
    const body = await c.req.json()
    const updated = await updateCrmCustomer(c.env.DB, id, body)
    if (!updated) {
      return c.json({ success: false, message: '未找到该客户' }, 404)
    }
    return c.json({ success: true, data: updated })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

crmRouter.delete('/crm/customers/:id', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const id = c.req.param('id')
    await deleteCrmCustomer(c.env.DB, id)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

crmRouter.post('/crm/customers/:id/new-cycle', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const id = c.req.param('id')
    const updated = await startNewCustomerCycle(c.env.DB, id, agent.id, agent.display_name)
    return c.json({ success: true, data: updated })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

crmRouter.get('/crm/followups', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const customerId = c.req.query('customer_id')
    const cycleStr = c.req.query('cycle_number')
    const cycleNumber = cycleStr ? Number(cycleStr) : undefined
    const list = await getCrmFollowups(c.env.DB, customerId, cycleNumber)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

crmRouter.post('/crm/followups', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const body = await c.req.json()
    if (!body.customer_id || !body.content || !body.content.trim()) {
      return c.json({ success: false, message: '请完整填写关联客户与跟进内容' }, 400)
    }

    const item = await createCrmFollowup(c.env.DB, {
      customer_id: body.customer_id,
      agent_id: agent.id,
      agent_name: agent.display_name,
      content: body.content.trim(),
      next_followup_time: body.next_followup_time ? Number(body.next_followup_time) : null,
      new_stage: body.new_stage || undefined
    })

    return c.json({ success: true, data: item })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

crmRouter.get('/crm/stats', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const stats = await getCrmStats(c.env.DB)
    return c.json({ success: true, data: stats })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})
