import type { Conversation, PageContext, ProductSnapshot, DeviceInfo, VisitorJourneyLog } from '../types'
import { findLeastLoadedOnlineAgent } from './auth'
import { getSettingForLang, DEFAULT_WELCOME_ZH } from '../../shared/langSettings'
import { ensureSitesSchema, getMergedSiteSettings } from './sites'

/**
 * 获取或创建访客会话（按站点隔离；支持坐席分配、多语言与页面上下文）
 */
export async function getOrCreateConversation(
  db: D1Database,
  visitorId: string,
  siteId: string,
  visitorName?: string,
  visitorLang?: string,
  geo?: { ip?: string; country?: string; city?: string; isp?: string; timezone?: string },
  contextData?: {
    page_context?: PageContext
    product_snapshot?: ProductSnapshot | null
    device_info?: DeviceInfo
  }
): Promise<{ conversation: Conversation; isNew: boolean }> {
  await ensureSitesSchema(db)
  // 确保兼容列存在
  try {
    await db.prepare('ALTER TABLE conversations ADD COLUMN ip TEXT DEFAULT NULL').run()
    await db.prepare('ALTER TABLE conversations ADD COLUMN country TEXT DEFAULT NULL').run()
    await db.prepare('ALTER TABLE conversations ADD COLUMN city TEXT DEFAULT NULL').run()
    await db.prepare('ALTER TABLE conversations ADD COLUMN assigned_agent_name TEXT DEFAULT NULL').run()
    await db.prepare("ALTER TABLE conversations ADD COLUMN platform TEXT DEFAULT 'web'").run()
    await db.prepare('ALTER TABLE conversations ADD COLUMN page_context TEXT DEFAULT NULL').run()
    await db.prepare('ALTER TABLE conversations ADD COLUMN product_snapshot TEXT DEFAULT NULL').run()
    await db.prepare('ALTER TABLE conversations ADD COLUMN device_info TEXT DEFAULT NULL').run()
    await db.prepare('ALTER TABLE conversations ADD COLUMN isp TEXT DEFAULT NULL').run()
    await db.prepare('ALTER TABLE conversations ADD COLUMN timezone TEXT DEFAULT NULL').run()
    await db.prepare(`CREATE TABLE IF NOT EXISTS visitor_journey_logs (
      id TEXT PRIMARY KEY,
      conversation_id TEXT NOT NULL,
      visitor_id TEXT NOT NULL,
      page_title TEXT,
      page_url TEXT NOT NULL,
      stay_seconds INTEGER DEFAULT 0,
      created_at INTEGER NOT NULL
    )`).run()
  } catch (e) {}

  if (!siteId) throw new Error('缺少站点')

  const pageContextJson = contextData?.page_context ? JSON.stringify(contextData.page_context) : null
  const productSnapshotJson = contextData?.product_snapshot ? JSON.stringify(contextData.product_snapshot) : null
  const deviceInfoJson = contextData?.device_info ? JSON.stringify(contextData.device_info) : null

  let conv = await db
    .prepare('SELECT * FROM conversations WHERE visitor_id = ? AND site_id = ?')
    .bind(visitorId, siteId)
    .first<Conversation>()

  if (conv) {
    // 若已有会话但尚未分配坐席，自动分配给最空闲的在线坐席
    if (!conv.assigned_agent_id) {
      const allocated = await findLeastLoadedOnlineAgent(db)
      if (allocated) {
        try {
          await db.prepare('UPDATE conversations SET assigned_agent_id = ?, assigned_agent_name = ? WHERE id = ?')
            .bind(allocated.id, allocated.name, conv.id).run()
          conv.assigned_agent_id = allocated.id
          conv.assigned_agent_name = allocated.name
        } catch (e) {}
      }
    }
    // 仅当 init 的 visitor_id 已匹配本会话时，才允许用请求里的昵称覆盖（归属已由查询保证）
    const trimmedName = (visitorName || '').trim().replace(/[<>]/g, '').slice(0, 64)
    if (
      trimmedName &&
      trimmedName !== conv.visitor_name &&
      !/^访客_?/.test(trimmedName) &&
      !/^Visitor_?/i.test(trimmedName)
    ) {
      try {
        await db.prepare('UPDATE conversations SET visitor_name = ? WHERE id = ?')
          .bind(trimmedName, conv.id)
          .run()
        conv.visitor_name = trimmedName
      } catch (e) {}
    }
    // 上下文与地理：有有效新值则覆盖（避免 COALESCE 把错误的 CF 基础设施 IP 永久锁死）
    try {
      const nextIp = geo?.ip?.trim() || null
      const nextCountry = geo?.country?.trim() || null
      const nextCity = geo?.city?.trim() || null
      const nextIsp = geo?.isp?.trim() || null
      const nextTz = geo?.timezone?.trim() || null
      await db.prepare(
        `UPDATE conversations SET
          ip = CASE WHEN ? IS NOT NULL THEN ? ELSE ip END,
          country = CASE WHEN ? IS NOT NULL THEN ? ELSE country END,
          city = CASE WHEN ? IS NOT NULL THEN ? ELSE city END,
          isp = CASE WHEN ? IS NOT NULL THEN ? ELSE isp END,
          timezone = CASE WHEN ? IS NOT NULL THEN ? ELSE timezone END,
          page_context = COALESCE(?, page_context),
          product_snapshot = COALESCE(?, product_snapshot),
          device_info = COALESCE(?, device_info)
        WHERE id = ?`
      ).bind(
        nextIp, nextIp,
        nextCountry, nextCountry,
        nextCity, nextCity,
        nextIsp, nextIsp,
        nextTz, nextTz,
        pageContextJson,
        productSnapshotJson,
        deviceInfoJson,
        conv.id
      ).run()
    } catch (e) {}

    // 记录访问足迹
    if (contextData?.page_context?.url) {
      try {
        const jId = `jny_${crypto.randomUUID().slice(0, 8)}`
        await db.prepare(
          'INSERT INTO visitor_journey_logs (id, conversation_id, visitor_id, page_title, page_url, stay_seconds, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)'
        ).bind(
          jId,
          conv.id,
          visitorId,
          contextData.page_context.title || null,
          contextData.page_context.url,
          contextData.page_context.stay_seconds || 0,
          Date.now()
        ).run()
      } catch (e) {}
    }

    // 重新拉取更新后的完整会话信息
    conv = await db.prepare('SELECT * FROM conversations WHERE id = ?').bind(conv.id).first<Conversation>()
    return { conversation: conv!, isNew: false }
  }

  const id = `conv_${crypto.randomUUID().slice(0, 8)}`
  const now = Date.now()
  const name = visitorName || `访客_${visitorId.slice(-4)}`

  // 智能分配：选取负载最低的在线坐席
  const allocated = await findLeastLoadedOnlineAgent(db)

  // 多语言欢迎语：取本站配置（空则回退全局默认）
  const settingsMap = await getMergedSiteSettings(db, siteId)
  let welcomeMsg = getSettingForLang(settingsMap, 'welcome_message', visitorLang || 'en', '')
  if (!welcomeMsg) {
    welcomeMsg =
      getSettingForLang(settingsMap, 'welcome_message', 'en', '') ||
      getSettingForLang(settingsMap, 'welcome_message', 'zh-CN', '') ||
      settingsMap.welcome_message ||
      DEFAULT_WELCOME_ZH
  }

  // 1. 插入新会话（绑定站点、坐席、地理、页面上下文）
  await db.prepare(
    `INSERT INTO conversations (
      id, visitor_id, visitor_name, site_id, group_id, status,
      unread_agent_count, unread_visitor_count, last_message_text,
      last_message_time, created_at, ip, country, city, isp, timezone,
      page_context, product_snapshot, device_info, assigned_agent_id, assigned_agent_name
    ) VALUES (?, ?, ?, ?, 'grp_default', 'active', 0, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(
    id,
    visitorId,
    name,
    siteId,
    welcomeMsg,
    now,
    now,
    geo?.ip || null,
    geo?.country || null,
    geo?.city || null,
    geo?.isp || null,
    geo?.timezone || null,
    pageContextJson,
    productSnapshotJson,
    deviceInfoJson,
    allocated?.id || null,
    allocated?.name || null
  ).run()

  // 2. 记录首次页面访问足迹
  if (contextData?.page_context?.url) {
    try {
      const jId = `jny_${crypto.randomUUID().slice(0, 8)}`
      await db.prepare(
        'INSERT INTO visitor_journey_logs (id, conversation_id, visitor_id, page_title, page_url, stay_seconds, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)'
      ).bind(
        jId,
        id,
        visitorId,
        contextData.page_context.title || null,
        contextData.page_context.url,
        contextData.page_context.stay_seconds || 0,
        now
      ).run()
    } catch (e) {}
  }

  // 3. 自动生成第一条欢迎系统消息（采用多语言宏模板，前端无缝动态切换）
  const welcomeMsgId = `msg_${crypto.randomUUID().slice(0, 8)}`
  const defaultWelcomeTemplate = welcomeMsg || '${welcome_default:您好！很高兴为您服务，请问有什么可以协助您的？}'
  await db.prepare(
    `INSERT INTO messages (
      id, conversation_id, sender_type, sender_id, sender_name,
      message_type, content, status, created_at
    ) VALUES (?, ?, 'agent', 'system', ?, 'text', ?, 'sent', ?)`
  ).bind(
    welcomeMsgId,
    id,
    '${system_agent:系统专属客服}',
    defaultWelcomeTemplate,
    now
  ).run()

  conv = await db.prepare('SELECT * FROM conversations WHERE id = ?').bind(id).first<Conversation>()
  return { conversation: conv!, isNew: true }
}

/**
 * 访客端动态更新页面足迹与商品快照 (SPA 路由无刷新切换)
 */
export async function updateConversationContext(
  db: D1Database,
  conversationId: string,
  visitorId: string,
  pageContext: PageContext,
  productSnapshot?: ProductSnapshot | null,
  deviceInfo?: DeviceInfo
): Promise<boolean> {
  const pageContextJson = JSON.stringify(pageContext)
  const productSnapshotJson = productSnapshot ? JSON.stringify(productSnapshot) : null
  const deviceInfoJson = deviceInfo ? JSON.stringify(deviceInfo) : null

  try {
    await db.prepare(
      `UPDATE conversations SET
        page_context = ?,
        product_snapshot = COALESCE(?, product_snapshot),
        device_info = COALESCE(?, device_info)
      WHERE id = ?`
    ).bind(pageContextJson, productSnapshotJson, deviceInfoJson, conversationId).run()

    if (pageContext.url) {
      const jId = `jny_${crypto.randomUUID().slice(0, 8)}`
      await db.prepare(
        'INSERT INTO visitor_journey_logs (id, conversation_id, visitor_id, page_title, page_url, stay_seconds, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)'
      ).bind(
        jId,
        conversationId,
        visitorId,
        pageContext.title || null,
        pageContext.url,
        pageContext.stay_seconds || 0,
        Date.now()
      ).run()
    }
    return true
  } catch (e) {
    console.error('Failed to update context', e)
    return false
  }
}

/**
 * 获取访客浏览旅程轨迹列表 (按时间正序)
 */
export async function getVisitorJourneyLogs(
  db: D1Database,
  conversationId: string
): Promise<VisitorJourneyLog[]> {
  try {
    const list = await db.prepare(
      'SELECT * FROM visitor_journey_logs WHERE conversation_id = ? ORDER BY created_at ASC LIMIT 100'
    ).bind(conversationId).all<VisitorJourneyLog>()
    return list.results || []
  } catch (e) {
    return []
  }
}

export async function getConversations(
  db: D1Database,
  opts?: {
    siteId?: string
    platform?: string
  }
): Promise<Conversation[]> {
  await ensureSitesSchema(db)
  try {
    await db.prepare("ALTER TABLE conversations ADD COLUMN platform TEXT DEFAULT 'web'").run()
  } catch (e) {}

  let sql = 'SELECT * FROM conversations WHERE 1=1'
  const params: any[] = []

  if (opts?.siteId) {
    sql += ' AND site_id = ?'
    params.push(opts.siteId)
  }

  if (opts?.platform) {
    sql += " AND (platform = ? OR (platform IS NULL AND ? = 'web'))"
    params.push(opts.platform, opts.platform)
  }

  sql += ' ORDER BY last_message_time DESC LIMIT 150'

  let stmt = db.prepare(sql)
  if (params.length > 0) stmt = stmt.bind(...params)
  const res = await stmt.all<Conversation>()
  return res.results || []
}

/**
 * 获取或创建 WhatsApp 专属渠道会话（归属指定站点）
 */
export async function getOrCreateWhatsAppConversation(
  db: D1Database,
  waId: string,
  senderName: string,
  siteId: string
): Promise<Conversation> {
  await ensureSitesSchema(db)
  const visitorId = `wa_${waId}`
  let conv = await db
    .prepare('SELECT * FROM conversations WHERE visitor_id = ? AND site_id = ?')
    .bind(visitorId, siteId)
    .first<Conversation>()
  const now = Date.now()

  if (conv) {
    if (senderName && conv.visitor_name !== senderName) {
      await db.prepare('UPDATE conversations SET visitor_name = ? WHERE id = ?').bind(senderName, conv.id).run()
      conv.visitor_name = senderName
    }
    return conv
  }

  const id = `conv_wa_${crypto.randomUUID().slice(0, 8)}`
  const allocated = await findLeastLoadedOnlineAgent(db)

  await db.prepare(`
    INSERT INTO conversations (
      id, visitor_id, visitor_name, site_id, group_id, status, platform,
      unread_agent_count, unread_visitor_count, last_message_text,
      last_message_time, created_at, assigned_agent_id, assigned_agent_name
    ) VALUES (?, ?, ?, ?, 'grp_default', 'active', 'whatsapp', 1, 0, 'WhatsApp 消息', ?, ?, ?, ?)
  `).bind(
    id,
    visitorId,
    senderName || `WhatsApp_${waId.slice(-4)}`,
    siteId,
    now,
    now,
    allocated?.id || null,
    allocated?.name || null
  ).run()

  return (await db.prepare('SELECT * FROM conversations WHERE id = ?').bind(id).first<Conversation>())!
}

/**
 * 插入来自 WhatsApp 同步的消息并更新会话
 */
export async function insertWhatsAppMessage(
  db: D1Database,
  conversationId: string,
  senderId: string,
  senderName: string,
  content: string
): Promise<void> {
  const msgId = `msg_wa_${crypto.randomUUID().slice(0, 8)}`
  const now = Date.now()

  await db.prepare(`
    INSERT INTO messages (
      id, conversation_id, sender_type, sender_id, sender_name,
      message_type, content, status, created_at
    ) VALUES (?, ?, 'visitor', ?, ?, 'text', ?, 'sent', ?)
  `).bind(msgId, conversationId, senderId, senderName, content, now).run()

  await db.prepare(`
    UPDATE conversations SET
      last_message_text = ?,
      last_message_time = ?,
      unread_agent_count = unread_agent_count + 1
    WHERE id = ?
  `).bind(content.slice(0, 80), now, conversationId).run()
}

/** 统计会话内图片/音视频/附件条数（删除前提示用） */
export async function countConversationMedia(
  db: D1Database,
  conversationId: string
): Promise<number> {
  try {
    const row = await db
      .prepare(
        "SELECT COUNT(*) as count FROM messages WHERE conversation_id = ? AND message_type IN ('image', 'audio', 'file', 'video')"
      )
      .bind(conversationId)
      .first<{ count: number }>()
    return row?.count || 0
  } catch {
    return 0
  }
}

/** 从消息 content 中提取 R2 object key（/media/ 之后） */
export async function listConversationMediaKeys(
  db: D1Database,
  conversationId: string
): Promise<string[]> {
  try {
    const res = await db
      .prepare(
        "SELECT content FROM messages WHERE conversation_id = ? AND message_type IN ('image', 'audio', 'file', 'video')"
      )
      .bind(conversationId)
      .all<{ content: string }>()

    const keys: string[] = []
    for (const row of res.results || []) {
      if (!row.content) continue
      const idx = row.content.indexOf('/media/')
      if (idx === -1) continue
      const fileKey = row.content.substring(idx + '/media/'.length).trim()
      if (fileKey) keys.push(fileKey)
    }
    return keys
  } catch {
    return []
  }
}

/**
 * 从 R2 存储桶物理删除该会话下的所有图片、音频、视频和附件文件
 * 必须在 DELETE messages 之前调用（或传入已收集的 keys）
 */
export async function deleteConversationMediaFromR2(
  db: D1Database,
  bucket: R2Bucket | undefined,
  conversationId: string,
  prefetchedKeys?: string[]
): Promise<number> {
  if (!bucket) return 0
  try {
    const keysToDelete = prefetchedKeys ?? (await listConversationMediaKeys(db, conversationId))
    if (keysToDelete.length === 0) return 0
    await Promise.allSettled(keysToDelete.map(k => bucket.delete(k)))
    return keysToDelete.length
  } catch (err) {
    console.error('Failed to cleanup R2 media for conversation', conversationId, err)
    return 0
  }
}

/**
 * 彻底物理级联删除会话：先收集并清理 R2，再删 D1（含足迹）
 */
export async function deleteConversation(
  db: D1Database,
  conversationId: string,
  bucket?: R2Bucket
): Promise<{ mediaCount: number; visitorId: string | null }> {
  const conv = await db
    .prepare('SELECT visitor_id FROM conversations WHERE id = ?')
    .bind(conversationId)
    .first<{ visitor_id: string }>()
  const visitorId = conv?.visitor_id || null

  // 1. 先取出媒体 key（消息删掉后就查不到了）
  const mediaKeys = await listConversationMediaKeys(db, conversationId)
  const mediaCount = mediaKeys.length

  // 2. 删 R2（允许短暂超时，避免拖死接口）
  if (bucket && mediaKeys.length > 0) {
    try {
      await Promise.race([
        deleteConversationMediaFromR2(db, bucket, conversationId, mediaKeys),
        new Promise(resolve => setTimeout(resolve, 8000))
      ])
    } catch (err) {
      console.warn('R2 media cleanup skipped or timed out', err)
    }
  }

  // 3. 再删 D1
  await db.prepare('DELETE FROM messages WHERE conversation_id = ?').bind(conversationId).run()
  try {
    await db.prepare('DELETE FROM visitor_journey_logs WHERE conversation_id = ?').bind(conversationId).run()
  } catch {
    /* 表可能不存在 */
  }
  await db.prepare('DELETE FROM conversations WHERE id = ?').bind(conversationId).run()

  if (conversationId.startsWith('sec_')) {
    await db.prepare('DELETE FROM private_chats WHERE id = ?').bind(conversationId).run()
  }

  return { mediaCount, visitorId }
}

/**
 * 更新会话的客户备注标签 (tag)
 */
export async function updateConversationTag(
  db: D1Database,
  conversationId: string,
  tag: string | null
): Promise<void> {
  try {
    await db.prepare('ALTER TABLE conversations ADD COLUMN tag TEXT DEFAULT NULL').run()
  } catch (e) {}

  await db.prepare(
    'UPDATE conversations SET tag = ? WHERE id = ?'
  ).bind(tag, conversationId).run()
}

/**
 * 批量清理垃圾会话：可清理未发言客户、按分组清理、按标签清理，同时删除 R2 文件
 */
export async function batchCleanupConversations(
  db: D1Database,
  bucket: R2Bucket | undefined,
  options: {
    cleanSilent?: boolean
    groupIds?: string[]
    tagMode?: 'all' | 'has_tag' | 'no_tag'
  }
): Promise<number> {
  try {
    await db.prepare('ALTER TABLE conversations ADD COLUMN tag TEXT DEFAULT NULL').run()
  } catch (e) {}

  const res = await db.prepare('SELECT id, group_id, tag FROM conversations').all<{ id: string; group_id: string; tag: string }>()
  const list = res.results || []
  const toDeleteIds: string[] = []

  for (const c of list) {
    let shouldDelete = false

    // 1. 未发言访客：统计访客发出的消息数是否为 0
    if (options.cleanSilent) {
      const msgRes = await db.prepare(
        "SELECT COUNT(*) as count FROM messages WHERE conversation_id = ? AND sender_type = 'visitor'"
      ).bind(c.id).first<{ count: number }>()
      if ((msgRes?.count || 0) === 0) {
        shouldDelete = true
      }
    }

    // 2. 按分组筛选清理
    if (!shouldDelete && options.groupIds && options.groupIds.length > 0) {
      if (options.groupIds.includes(c.group_id || 'grp_default')) {
        shouldDelete = true
      }
    }

    // 3. 按标签筛选清理
    if (!shouldDelete && options.tagMode) {
      const hasTag = Boolean(c.tag && c.tag.trim())
      if (options.tagMode === 'has_tag' && hasTag) {
        shouldDelete = true
      } else if (options.tagMode === 'no_tag' && !hasTag) {
        shouldDelete = true
      }
    }

    if (shouldDelete) {
      toDeleteIds.push(c.id)
    }
  }

  for (const cid of toDeleteIds) {
    await deleteConversation(db, cid, bucket)
  }

  return toDeleteIds.length
}
