import type { Message } from '../types'

/**
 * 增量游标分片拉取消息
 * @param beforeTime 拉取早于此时间戳（向上翻页）
 * @param afterTime 拉取晚于此时间戳（访客清除本地后只同步新消息）
 */
export async function getMessagesByConversation(
  db: D1Database,
  conversationId: string,
  limit: number = 40,
  beforeTime?: number,
  afterTime?: number
): Promise<Message[]> {
  let query = 'SELECT * FROM messages WHERE conversation_id = ?'
  const params: any[] = [conversationId]

  if (beforeTime && beforeTime > 0) {
    query += ' AND created_at < ?'
    params.push(beforeTime)
  }
  if (afterTime && afterTime > 0) {
    query += ' AND created_at > ?'
    params.push(afterTime)
  }

  query += ' ORDER BY created_at DESC LIMIT ?'
  params.push(limit)

  const res = await db.prepare(query).bind(...params).all<Message>()
  const list = res.results || []

  return list.reverse()
}

export async function insertMessage(
  db: D1Database,
  msg: Omit<Message, 'created_at'> & { created_at?: number }
): Promise<Message> {
  const createdAt = msg.created_at || Date.now()
  const fullMsg: Message = {
    ...msg,
    created_at: createdAt
  }

  await db.prepare(
    `INSERT INTO messages (
      id, conversation_id, sender_type, sender_id, sender_name,
      message_type, content, extra_json, status, created_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(
    fullMsg.id,
    fullMsg.conversation_id,
    fullMsg.sender_type,
    fullMsg.sender_id,
    fullMsg.sender_name,
    fullMsg.message_type,
    fullMsg.content,
    fullMsg.extra_json || null,
    fullMsg.status,
    fullMsg.created_at
  ).run()

  let summary = fullMsg.content
  if (fullMsg.message_type === 'image') summary = '[图片]'
  else if (fullMsg.message_type === 'audio') summary = '[语音]'
  else if (fullMsg.message_type === 'file') summary = '[文件]'

  if (fullMsg.sender_type === 'visitor') {
    await db.prepare(
      `UPDATE conversations SET 
        last_message_text = ?, 
        last_message_time = ?, 
        unread_agent_count = unread_agent_count + 1 
       WHERE id = ?`
    ).bind(summary, createdAt, fullMsg.conversation_id).run()
  } else {
    await db.prepare(
      `UPDATE conversations SET 
        last_message_text = ?, 
        last_message_time = ?, 
        unread_visitor_count = unread_visitor_count + 1 
       WHERE id = ?`
    ).bind(summary, createdAt, fullMsg.conversation_id).run()
  }

  return fullMsg
}

export async function markConversationAsRead(
  db: D1Database,
  conversationId: string,
  byRole: 'visitor' | 'agent'
): Promise<void> {
  if (byRole === 'agent') {
    await db.prepare('UPDATE conversations SET unread_agent_count = 0 WHERE id = ?').bind(conversationId).run()
  } else {
    await db.prepare('UPDATE conversations SET unread_visitor_count = 0 WHERE id = ?').bind(conversationId).run()
  }
}
