import { Hono } from 'hono'
import type { Env } from '../types'
import { getAllAgents, createAgent, updateAgent, deleteAgent } from '../db/auth'
import { getDashboardStats } from '../db/stats'
import { getSystemSettings, updateSystemSettings } from '../db/settings'
import { isErrorResponse, requireAdmin, requireAgent } from '../middleware/auth'

export const adminRouter = new Hono<{ Bindings: Env }>()

adminRouter.get('/agents', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const list = await getAllAgents(c.env.DB)
    return c.json({ success: true, data: list })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

adminRouter.post('/agents', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const body = await c.req.json()
    const { username, password, display_name, role } = body
    if (!username || !password || !display_name) {
      return c.json({ success: false, message: '请完整填写员工信息' }, 400)
    }
    const id = await createAgent(c.env.DB, { username, password, display_name, role })
    return c.json({ success: true, data: { id } })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 400)
  }
})

adminRouter.put('/agents/:id', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const id = c.req.param('id')
    const body = await c.req.json()
    await updateAgent(c.env.DB, id, body)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 400)
  }
})

adminRouter.delete('/agents/:id', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const id = c.req.param('id')
    await deleteAgent(c.env.DB, id)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 400)
  }
})

adminRouter.get('/stats', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const siteId = (c.req.query('site_id') || c.req.header('X-Site-Id') || '').trim()
    if (siteId) {
      const { agentCanAccessSite } = await import('../db/sites')
      if (!(await agentCanAccessSite(c.env.DB, agent, siteId))) {
        return c.json({ success: false, message: '无权查看该站点统计' }, 403)
      }
    }
    const stats = await getDashboardStats(c.env.DB, siteId || undefined)
    return c.json({ success: true, data: stats })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

/** 读出时脱敏；写入时若为占位符则跳过（保留库内原值） */
const SETTINGS_SECRET_KEYS = new Set([
  'ga_oauth_refresh_token',
  'ga_oauth_access_cache',
  'ga_oauth_state',
  'ga_oauth_client_secret'
])

adminRouter.get('/settings', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent
    const data = await getSystemSettings(c.env.DB)
    for (const k of SETTINGS_SECRET_KEYS) {
      if (data[k]) data[k] = '__configured__'
    }
    return c.json({ success: true, data })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

adminRouter.post('/settings', async (c) => {
  try {
    const admin = await requireAdmin(c)
    if (isErrorResponse(admin)) return admin
    const body = await c.req.json()
    // 会话类机密禁止经通用设置写入
    delete body.ga_oauth_refresh_token
    delete body.ga_oauth_access_cache
    delete body.ga_oauth_state
    // 客户端密钥：空或占位则不覆盖已保存值
    if (
      !body.ga_oauth_client_secret ||
      body.ga_oauth_client_secret === '__configured__'
    ) {
      delete body.ga_oauth_client_secret
    }
    await updateSystemSettings(c.env.DB, body)
    return c.json({ success: true })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

