import { Hono } from 'hono'
import type { Env } from '../types'
import { verifyAgent, updateAgentStatus, updateCurrentProfile } from '../db/auth'
import { verifyTurnstileToken } from '../utils/turnstile'
import { issueAgentToken } from '../utils/sessionToken'
import { clientIp, enforceRateLimit } from '../utils/rateLimit'
import { isErrorResponse, requireAgent } from '../middleware/auth'
import { internalRequestHeaders } from '../utils/sessionToken'

export const authRouter = new Hono<{ Bindings: Env }>()

authRouter.get('/turnstile-config', async (c) => {
  const siteKey = (c.env.TURNSTILE_SITE_KEY || '').trim()
  const isProduction = !!siteKey && !siteKey.startsWith('1x')
  return c.json({
    success: true,
    data: {
      site_key: isProduction ? siteKey : '',
      is_production: isProduction
    }
  })
})

authRouter.post('/login', async (c) => {
  try {
    const rl = await enforceRateLimit({
      key: `login:${clientIp(c)}`,
      limit: 20,
      windowSec: 300
    })
    if (!rl.ok) {
      return c.json({ success: false, message: '登录尝试过于频繁，请稍后再试' }, 429)
    }

    const { username, password, security_code, turnstile_token } = await c.req.json()

    if (!username || !password) {
      return c.json({ success: false, message: '请输入用户名和密码' }, 400)
    }

    const expectedSecurityCode = c.env.ADMIN_SECURITY_CODE
    if (expectedSecurityCode) {
      if (!security_code || security_code.trim() !== expectedSecurityCode.trim()) {
        return c.json({ success: false, message: '后台安全码验证失败，请确认安全码正确' }, 403)
      }
    }

    const isValidHuman = await verifyTurnstileToken(
      turnstile_token,
      c.env.TURNSTILE_SECRET_KEY,
      clientIp(c)
    )
    if (!isValidHuman) {
      return c.json({ success: false, message: '人机验证失败，请刷新重试' }, 403)
    }

    const agent = await verifyAgent(c.env.DB, username, password)
    if (!agent) {
      return c.json({ success: false, message: '用户名或密码错误' }, 401)
    }

    await updateAgentStatus(c.env.DB, agent.id, 'online')
    const token = await issueAgentToken(c.env, { id: agent.id, role: agent.role as 'admin' | 'agent' })

    return c.json({
      success: true,
      data: {
        id: agent.id,
        username: agent.username,
        display_name: agent.display_name,
        role: agent.role,
        status: 'online',
        token
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

authRouter.post('/status', async (c) => {
  const agent = await requireAgent(c)
  if (isErrorResponse(agent)) return agent

  const { status } = await c.req.json()
  if (!status) {
    return c.json({ success: false, message: '缺少参数' }, 400)
  }
  await updateAgentStatus(c.env.DB, agent.id, status)

  try {
    const res = await c.env.DB.prepare("SELECT count(1) as count FROM agents WHERE status = 'online'").first<{
      count: number
    }>()
    const count = res?.count || 0
    const stub = c.env.COORDINATOR.get(c.env.COORDINATOR.idFromName('global_chat_coordinator'))
    await stub.fetch(
      new Request('http://coordinator/broadcast-status', {
        method: 'POST',
        headers: internalRequestHeaders(c.env),
        body: JSON.stringify({ has_online: count > 0, online_count: count })
      })
    )
  } catch (e) {}

  return c.json({ success: true, status })
})

authRouter.get('/online-status', async (c) => {
  try {
    const res = await c.env.DB.prepare("SELECT count(1) as count FROM agents WHERE status = 'online'").first<{
      count: number
    }>()
    const count = res?.count || 0
    c.header('Cache-Control', 'public, max-age=60, s-maxage=60')
    return c.json({
      success: true,
      data: {
        has_online: count > 0,
        online_count: count
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 500)
  }
})

authRouter.get('/me', async (c) => {
  const agent = await requireAgent(c)
  if (isErrorResponse(agent)) return agent
  return c.json({
    success: true,
    data: {
      id: agent.id,
      username: agent.username,
      display_name: agent.display_name,
      role: agent.role,
      status: agent.status
    }
  })
})

authRouter.post('/profile', async (c) => {
  try {
    const agent = await requireAgent(c)
    if (isErrorResponse(agent)) return agent

    const body = await c.req.json()
    const { username, display_name, old_password, new_password } = body
    if (!username || !display_name) {
      return c.json({ success: false, message: '请完整填写用户名和姓名' }, 400)
    }

    const updated = await updateCurrentProfile(c.env.DB, agent.id, {
      username,
      display_name,
      old_password,
      new_password
    })

    const token = await issueAgentToken(c.env, {
      id: updated.id,
      role: updated.role as 'admin' | 'agent'
    })

    return c.json({
      success: true,
      data: {
        id: updated.id,
        username: updated.username,
        display_name: updated.display_name,
        role: updated.role,
        status: updated.status,
        token
      }
    })
  } catch (err: any) {
    return c.json({ success: false, message: err.message }, 400)
  }
})
