import type { CustomForm, FormLocaleBundle, FormSubmission, FormStyleConfig } from '../../shared/types'
import { displayFormTitle, emptyFormLocaleBundle } from '../../shared/formI18n'

/**
 * 确保通用表单所需的两张数据表存在
 */
export async function ensureFormTables(db: D1Database): Promise<void> {
  await db.prepare(`
    CREATE TABLE IF NOT EXISTS custom_forms (
      id TEXT PRIMARY KEY,
      key TEXT NOT NULL,
      site_id TEXT,
      title TEXT NOT NULL,
      description TEXT,
      allowed_domains TEXT,
      fields_json TEXT NOT NULL,
      style_config_json TEXT,
      translations_json TEXT,
      status TEXT DEFAULT 'active',
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    )
  `).run()

  // 已有库补列（忽略重复）
  try {
    await db.prepare('ALTER TABLE custom_forms ADD COLUMN translations_json TEXT').run()
  } catch {
    /* already exists */
  }
  try {
    await db.prepare('ALTER TABLE custom_forms ADD COLUMN site_id TEXT').run()
  } catch {
    /* already exists */
  }

  await db.prepare(`
    CREATE TABLE IF NOT EXISTS form_submissions (
      id TEXT PRIMARY KEY,
      form_key TEXT NOT NULL,
      form_id TEXT,
      site_id TEXT,
      visitor_id TEXT,
      data_json TEXT NOT NULL,
      ip TEXT,
      country TEXT,
      city TEXT,
      source_url TEXT,
      created_at INTEGER NOT NULL
    )
  `).run()

  try {
    await db.prepare('ALTER TABLE form_submissions ADD COLUMN site_id TEXT').run()
  } catch {
    /* already exists */
  }

  try {
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_custom_forms_key ON custom_forms(key)').run()
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_custom_forms_site ON custom_forms(site_id)').run()
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_custom_forms_site_key ON custom_forms(site_id, key)').run()
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_form_subs_key ON form_submissions(form_key)').run()
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_form_subs_site ON form_submissions(site_id)').run()
  } catch {
    /* ignore */
  }
}

const DEFAULT_STYLE: FormStyleConfig = {
  primary_color: '#07c160',
  bg_color: 'white',
  border_radius: 5,
  size: 'medium'
}

function rowToForm(r: any, submissionsCount = 0): CustomForm {
  let fields: CustomForm['fields'] = []
  let style: FormStyleConfig = { ...DEFAULT_STYLE }
  let translations: Record<string, FormLocaleBundle> = {}

  try {
    fields = JSON.parse(r.fields_json || '[]')
  } catch {
    fields = []
  }
  try {
    if (r.style_config_json) {
      const parsed = JSON.parse(r.style_config_json)
      style = {
        primary_color: parsed.primary_color || DEFAULT_STYLE.primary_color,
        bg_color: parsed.bg_color || 'white',
        border_radius: typeof parsed.border_radius === 'number' ? parsed.border_radius : 5,
        size: parsed.size || 'medium'
      }
    }
  } catch {
    /* keep default */
  }
  try {
    if (r.translations_json) translations = JSON.parse(r.translations_json)
  } catch {
    translations = {}
  }

  // 无 translations 时用 title 列兜底成单一默认包（开发空库场景）
  if (!translations || Object.keys(translations).length === 0) {
    translations = {
      'zh-CN': {
        ...emptyFormLocaleBundle(),
        title: r.title || '',
        description: r.description || ''
      }
    }
  }

  return {
    id: r.id,
    key: r.key,
    site_id: r.site_id || '',
    allowed_domains: r.allowed_domains || '',
    fields,
    translations_json: translations,
    style,
    status: r.status || 'active',
    submissions_count: submissionsCount,
    created_at: r.created_at,
    updated_at: r.updated_at
  }
}

function listTitle(translations: Record<string, FormLocaleBundle>, fallbackKey: string): string {
  return displayFormTitle({ translations_json: translations, key: fallbackKey }, 'zh-CN')
}

export async function getAllCustomForms(db: D1Database, siteId: string): Promise<CustomForm[]> {
  await ensureFormTables(db)
  const rows = await db
    .prepare('SELECT * FROM custom_forms WHERE site_id = ? ORDER BY created_at DESC')
    .bind(siteId)
    .all<any>()
  if (!rows.results) return []

  const forms: CustomForm[] = []
  for (const r of rows.results) {
    const countRow = await db
      .prepare(
        'SELECT COUNT(id) as count FROM form_submissions WHERE form_key = ? AND (site_id = ? OR site_id IS NULL OR site_id = \'\')'
      )
      .bind(r.key, siteId)
      .first<{ count: number }>()
    forms.push(rowToForm(r, countRow?.count || 0))
  }
  return forms
}

export async function getCustomFormByKey(
  db: D1Database,
  key: string,
  siteId: string
): Promise<CustomForm | null> {
  await ensureFormTables(db)
  const r = await db
    .prepare('SELECT * FROM custom_forms WHERE key = ? AND site_id = ?')
    .bind(key, siteId)
    .first<any>()
  if (!r) return null
  return rowToForm(r)
}

export async function getCustomFormById(db: D1Database, id: string): Promise<CustomForm | null> {
  await ensureFormTables(db)
  const r = await db.prepare('SELECT * FROM custom_forms WHERE id = ?').bind(id).first<any>()
  if (!r) return null
  return rowToForm(r)
}

export async function createCustomForm(
  db: D1Database,
  data: {
    key: string
    site_id: string
    allowed_domains?: string
    fields: CustomForm['fields']
    style: FormStyleConfig
    translations_json: Record<string, FormLocaleBundle>
  }
): Promise<CustomForm> {
  await ensureFormTables(db)
  if (!data.site_id) throw new Error('site_id 为必填项')

  const id = `form_${Date.now().toString(36)}_${crypto.randomUUID().slice(0, 4)}`
  const now = Date.now()
  const title = listTitle(data.translations_json, data.key)

  await db
    .prepare(`
    INSERT INTO custom_forms (
      id, key, site_id, title, description, allowed_domains,
      fields_json, style_config_json, translations_json, status, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)
  `)
    .bind(
      id,
      data.key,
      data.site_id,
      title,
      '',
      data.allowed_domains || '',
      JSON.stringify(data.fields || []),
      JSON.stringify(data.style || DEFAULT_STYLE),
      JSON.stringify(data.translations_json || {}),
      now,
      now
    )
    .run()

  return (await getCustomFormByKey(db, data.key, data.site_id))!
}

export async function updateCustomForm(
  db: D1Database,
  id: string,
  data: {
    allowed_domains?: string
    fields: CustomForm['fields']
    style: FormStyleConfig
    translations_json: Record<string, FormLocaleBundle>
  }
): Promise<void> {
  await ensureFormTables(db)
  const now = Date.now()
  const title = listTitle(data.translations_json, id)

  await db
    .prepare(`
    UPDATE custom_forms SET
      title = ?,
      description = ?,
      allowed_domains = ?,
      fields_json = ?,
      style_config_json = ?,
      translations_json = ?,
      updated_at = ?
    WHERE id = ?
  `)
    .bind(
      title,
      '',
      data.allowed_domains || '',
      JSON.stringify(data.fields || []),
      JSON.stringify(data.style || DEFAULT_STYLE),
      JSON.stringify(data.translations_json || {}),
      now,
      id
    )
    .run()
}

export async function deleteCustomForm(db: D1Database, id: string): Promise<void> {
  await ensureFormTables(db)
  const form = await db
    .prepare('SELECT key, site_id FROM custom_forms WHERE id = ?')
    .bind(id)
    .first<{ key: string; site_id: string }>()
  if (form) {
    await db
      .prepare('DELETE FROM form_submissions WHERE form_key = ? AND (site_id = ? OR site_id IS NULL OR site_id = \'\')')
      .bind(form.key, form.site_id || '')
      .run()
  }
  await db.prepare('DELETE FROM custom_forms WHERE id = ?').bind(id).run()
}

export async function getFormSubmissions(
  db: D1Database,
  formKey: string,
  siteId: string
): Promise<FormSubmission[]> {
  await ensureFormTables(db)
  const rows = await db
    .prepare(
      `SELECT * FROM form_submissions
       WHERE form_key = ? AND (site_id = ? OR site_id IS NULL OR site_id = '')
       ORDER BY created_at DESC LIMIT 500`
    )
    .bind(formKey, siteId)
    .all<any>()

  if (!rows.results) return []

  return rows.results.map(r => {
    let data = {}
    try {
      data = JSON.parse(r.data_json)
    } catch {
      data = {}
    }
    return {
      id: r.id,
      form_key: r.form_key,
      form_id: r.form_id,
      site_id: r.site_id || siteId,
      visitor_id: r.visitor_id,
      data,
      ip: r.ip,
      country: r.country,
      city: r.city,
      source_url: r.source_url,
      created_at: r.created_at
    }
  })
}

export async function insertFormSubmission(
  db: D1Database,
  data: {
    form_key: string
    site_id: string
    visitor_id?: string
    data: Record<string, any>
    ip?: string
    country?: string
    city?: string
    source_url?: string
  }
): Promise<string> {
  await ensureFormTables(db)
  const id = `sub_${Date.now().toString(36)}_${crypto.randomUUID().slice(0, 4)}`
  const now = Date.now()

  await db
    .prepare(`
    INSERT INTO form_submissions (
      id, form_key, site_id, visitor_id, data_json, ip, country, city, source_url, created_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `)
    .bind(
      id,
      data.form_key,
      data.site_id,
      data.visitor_id || 'anonymous',
      JSON.stringify(data.data),
      data.ip || '',
      data.country || '',
      data.city || '',
      data.source_url || '',
      now
    )
    .run()

  return id
}

export async function deleteFormSubmission(db: D1Database, id: string): Promise<void> {
  await ensureFormTables(db)
  await db.prepare('DELETE FROM form_submissions WHERE id = ?').bind(id).run()
}
